// Setiap pelajaran: { s:slug, t:judul, mn:minit, sum:satu baris, p:[perenggan],
// k:[pengajaran], q:{ s:soalan, o:[pilihan], a:indeks betul, e:penerangan } }
const LESSONS = {
  sky: [
    { s: 'reading-the-night-sky', t: 'Reading the Night Sky', mn: 7,
      sum: 'Why stars rise and set, what constellations really are, and how light pollution erases them.',
      p: [
        'The sky works like a giant clock face turning around you once a day — that is Earth spinning, not the stars orbiting us. Near the poles of that turn sit the anchor stars: Polaris in the north, roughly above the North Pole, and (far less helpful) Sigma Octantis in the south. Find one, and you can face any direction without a compass — the same trick sailors used for millennia.',
        'A constellation is not a thing out there — it is a pattern you impose. The stars of Orion sit at wildly different distances, some 250 light years away and others more than 1,000, but all project onto one “hunter” from our vantage point. The sky is a flat map of a deep room. Two people on opposite ends of Earth never see the same full sky: you cannot see the Southern Cross from London, and no one in Australia sees the Big Dipper high overhead.',
        'The enemy of all this is light. Around a third of the world’s population lives under skies bright enough that the Milky Way simply vanishes — a real measurement made by satellite. The fix is dull: shielded downward lighting. Under a dark sky, the naked eye shows about 2,500 stars at once; under city lights, closer to 20. The universe has not changed; your ceiling has.',
      ],
      k: ['Stars rising in the east and setting in the west is Earth rotating, not the sky moving', 'Constellations are projected patterns — the stars inside one are at very different distances', 'Light pollution hides the Milky Way from roughly a third of humanity'],
      q: { s: 'Why can two people on Earth never see the identical night sky at the same moment?', o: ['The stars move quickly', 'Opposite hemispheres look into opposite halves of the sky', 'The Moon blocks one side'], a: 1, e: 'Earth is a sphere: each hemisphere looks outward into a different half of space, and some stars stay permanently below the other’s horizon.' } },
    { s: 'moon-phases-tides', t: 'The Moon, Phases and Tides', mn: 8,
      sum: 'Phases are geometry, not shadows — and the same Moon drags the oceans twice a day.',
      p: [
        'Every phase you see is one half of the Moon being lit by the Sun and your view slicing that lit half at a different angle. A crescent is not “Earth’s shadow on the Moon” — Earth’s shadow on the Moon is an eclipse, and it can only happen at full Moon. The slow-changing “Earthshine” on the dark part of a crescent is sunlight bounced off our own planet onto the Moon and back — the classic test of whether the telescope age had begun to see clearly.',
        'The Moon recedes from Earth by about 3.8 centimetres a year — measured by bouncing lasers off mirrors left by the Apollo missions. That small change lengthens our day by roughly a millisecond or two per century. Tides are the friction behind it: the Moon’s gravity pulls harder on the near side of Earth than the far side, and the oceans stretch into two bulges — one facing the Moon, one opposite. As Earth turns under those bulges, most coasts get two high tides about 12 hours and 25 minutes apart, not 12.',
        'When Sun and Moon align — full or new Moon — the bulges stack: spring tides, the biggest. At quarter phases they partially cancel: neap tides, the smallest. “Spring” here has nothing to do with the season; it means the sea springing up.',
      ],
      k: ['Phases are viewing geometry; Earth’s shadow only falls on the Moon during eclipses', 'Two tidal bulges + Earth’s rotation = two high tides ~12h 25m apart', 'The Moon drifts away ~3.8 cm/year, slowly lengthening our day'],
      q: { s: 'A thin crescent Moon is partly dark because:', o: ['Earth’s shadow covers it', 'The far side of the Moon is in darkness and we see the boundary at an angle', 'Clouds dim it'], a: 1, e: 'The dark part is simply the unlit half of the Moon seen edge-on. Earth’s shadow on the Moon only occurs during a lunar eclipse at full Moon.' } },
    { s: 'eclipses-safely', t: 'Eclipses — Rare Maths in the Sky', mn: 7,
      sum: 'Why eclipses don’t happen every month, and the only safe way to look.',
      p: [
        'If the Moon’s orbit lay flat with Earth’s orbit around the Sun, we would get a solar and a lunar eclipse every single month. It does not: the Moon’s path tilts about five degrees, so most months its shadow misses Earth entirely, or Earth’s shadow misses the Moon. When the alignment is exact, a solar eclipse happens — and the Moon’s shadow traces a narrow band, typically under 250 kilometres wide. Stand outside that ribbon of totality and you see a partial bite, not a corona.',
        'The uncanny arithmetic behind totality: the Sun is about 400 times wider than the Moon, and also about 400 times farther away, so the two discs match in the sky. That match is a temporary gift of geology — with the Moon slowly receding, total solar eclipses as we know them will one day be impossible. Somewhere on Earth an eclipse of some kind happens roughly every 18 months, but any single point waits centuries between totalities.',
        'Safety is not negotiable: looking at a partial or ring (annular) Sun with the naked eye, or with ordinary sunglasses or smoked glass, can burn the retina with no pain at all. Only ISO 12312-2 certified filters — or a projected pinhole image — are safe for the Sun’s disc. The one exception: during the few minutes of totality, when the Moon fully covers the Sun’s surface, naked-eye viewing is genuinely safe. If it is not total, never look.',
      ],
      k: ['The 5° tilt of the Moon’s orbit is why eclipses are rare, not monthly', 'Totality needs the Moon’s ~200 km shadow ribbon — location matters more than date', 'Only certified solar filters are safe, except during the brief minutes of totality'],
      q: { s: 'Why isn’t there a solar eclipse every new Moon?', o: ['New Moons sometimes happen behind the Sun’s glare', 'The Moon’s orbit is tilted, so its shadow usually misses Earth', 'The Moon’s phase cycle is longer than a month'], a: 1, e: 'Because of the ~5° tilt, the Moon usually passes above or below the Earth–Sun line at new Moon. Exact crossings are what make eclipse seasons.' } },
    { s: 'planets-wanderers', t: 'The Five Wanderers', mn: 7,
      sum: 'What makes a planet a planet, why Mars loops backwards, and why only five are visible.',
      p: [
        '“Planet” comes from the Greek for wanderer: to naked-eye observers the five bright wanderers — Mercury, Venus, Mars, Jupiter, Saturn — slid against the fixed star pattern over weeks, while stars held their shapes. They are still the only planets you can see without help, and even then you must catch Venus near dawn or dusk, Mars when it is bright at opposition, and Mercury low in twilight. Nothing about being “visible to the eye” makes those five special in space — it is simply chemistry of the early solar system: big, bright, close.',
        'Planets orbit the Sun inside out: Mercury whips round in 88 days, Earth in 365, Jupiter in nearly 12 years. Every outer planet therefore gets overtaken by Earth periodically — and during the pass, the outer planet appears to slow, reverse, loop, then resume. This “retrograde” loop is pure perspective, like a car you pass seeming to fall backwards against the scenery. Mars does it roughly every 26 months at opposition, which is precisely when astronomers point their telescopes at it.',
        'The 2006 reclassification of Pluto was not a demotion of a “ninth planet we dislike” but a definition fix: the solar system turned out to hold thousands of icy bodies sharing Pluto’s zone, and anything that dominates its orbit is a planet while anything coexisting there is a dwarf. The line is about orbital real estate, and by that test Earth, Mars, Jupiter and the rest pass cleanly.',
      ],
      k: ['Only Mercury, Venus, Mars, Jupiter and Saturn are visible without a telescope', 'Retrograde loops are a perspective effect of Earth overtaking outer planets', 'The planet/dwarf-planet line is drawn by whether a body dominates its orbit'],
      q: { s: 'Mars appears to move backwards in the sky a few months every ~26 months because:', o: ['Mars briefly reverses its orbit', 'Earth, on a faster inner orbit, overtakes it', 'The Sun’s gravity pulls Mars sideways'], a: 1, e: 'It is relative motion — as Earth passes Mars on the inside lane, Mars appears to shift westward against the stars, exactly like a passed car seeming to move back.' } },
    { s: 'stars-lifecycles', t: 'Stars Are Clocks', mn: 8,
      sum: 'Light-years, the Sun’s midlife, and why the iron in your blood came from explosions.',
      p: [
        'A light-year is a distance, not a time — about 9.5 trillion kilometres. When you see Orion, its nearest bright stars are around 250 light-years off, so the pattern left your retina’s data centuries ago in the sense that its information is centuries old. Nothing in the night sky is “now”: the only truly present object overhead is the Moon, 1.3 light-seconds away. Looking farther is literally looking back in time, which is why telescopes are the closest thing to a time machine astronomy owns.',
        'Stars are thermonuclear engines fusing hydrogen into helium, and their mass sets their lifespan: small red dwarfs burn for trillions of years; the Sun, mid-sized, gets about 10 billion in total and is just over halfway; huge blue stars are spent in a few million. When stars like the Sun exhaust fuel they shed their outer layers and leave a white dwarf — Earth-sized, teaspoon-heavy. The giants explode as supernovae, and inside those explosions (and inside the stars before them) elements heavier than helium are forged. The calcium in your bones, the iron in your blood — astronomically speaking, all of it is recycled star exhaust.',
        'Betelgeuse, the red supergiant in Orion, is the famous “might explode any time” star — “any time” meaning within the next hundred thousand years or so, and possibly already decades past if it has, its light still arriving. When it finally does, it will not harm Earth (about 500–700 light-years away) but will briefly shine as bright as Venus in daylight.',
      ],
      k: ['Every star you see is history — light left years to centuries ago', 'Mass sets lifespan: dwarf stars outlive big ones by millions of years', 'Heavy atoms were made in stars and explosions, not in the Big Bang'],
      q: { s: 'Why is a light-year useful to astronomers?', o: ['It measures how fast light travels', 'It measures enormous distances while also meaning “time machine”', 'It measures a star’s brightness'], a: 1, e: 'It is a distance unit (about 9.5 trillion km) — and because light takes time to cross it, larger distances automatically show the past.' } },
  ],
  weather: [
    { s: 'reading-a-forecast', t: 'Reading a Forecast', mn: 7,
      sum: 'Humidity, pressure and fronts — the small print your weather app hides.',
      p: [
        'Temperature on a forecast is standardized: a thermometer in a louvered box, about two metres above grass, in the shade, with air flowing — not what your asphalt car park experiences. Humidity is almost always relative humidity: the share of water the air could hold at that temperature, already full, out of its maximum. So 50% at 30 °C carries far more actual water than 80% at 10 °C — “humid” is a feeling, not a number, and the number that tracks the feeling is the dew point: above roughly 20 °C dew point, sweat stops doing its cooling job.',
        'Pressure is forecast gold because air flows from high to low and the trend predicts the next day: a slowly falling barometer usually means a warm, moist low approaching — often 12 to 24 hours ahead of rain. Rising pressure generally means clearing and drying. A “front” is just the boundary between two air masses; cold fronts ride under warm air and force it up fast, giving short hard showers, while warm fronts slide gently over, giving long steady rain and drizzle.',
        'Forecast “probability of rain” (PoP) is commonly misunderstood even by weather services’ own surveys: it means the chance that at least a measurable amount falls at your point, whatever the amount. A 30% PoP can still mean a flood down the road; a 90% PoP can mean 15 minutes of drizzle. For the size of the event you need the quantitative forecast, not the percentage.',
      ],
      k: ['Relative humidity only makes sense with temperature — dew point is the honest comfort number', 'Falling pressure typically hints at rain within a day; rising pressure at clearing', '“30% chance of rain” is about whether it falls at all, not how much'],
      q: { s: 'Two days both show 80% humidity. Day A is 12 °C, Day B is 30 °C. Which feels more muggy?', o: ['Day A', 'Day B', 'Identical — same humidity'], a: 1, e: 'At 30 °C, 80% relative humidity means much more actual water in the air than at 12 °C. Dew point, not relative humidity, tracks the sticky feeling.' } },
    { s: 'how-rain-forms', t: 'How Rain Forms', mn: 7,
      sum: 'Cloud drops are too small to fall — rain needs a growth trick.',
      p: [
        'A cloud is not steam and it is not about to “get heavy enough to drop”. It is a suspension of microscopic water or ice particles, typically 10–20 micrometres across, so light that rising air keeps them aloft indefinitely — a cumulus cloud can weigh close to a million tonnes yet float like it weighs nothing. For rain, each particle must grow roughly a hundred times in diameter, and clouds have two engines to do that.',
        'In warm clouds, drops collide and merge — bigger falls through the cloud, sweeping up smaller ones, growing with every pickup until it finally outfalls the updraft. That is why tropical rain starts as fat, widely spaced drops. In cold clouds the trick is stranger: ice crystals and supercooled droplets can coexist, and because air holds less vapour over ice than over water, vapour migrates onto the ice, which fattens at the droplets’ expense until it falls — melting into rain on the way down. Most mid-latitude rain, and every snowflake, began with an ice crystal.',
        'Even those tiny droplets usually needed help forming at all: water vapour cannot easily condense out of thin air onto nothing, so it condenses onto microscopic nuclei — dust, smoke, sea salt, even pollen and bacterial fragments. Clean air makes fewer, larger drops; polluted air makes more, tinier ones — which is why pollution can suppress rain while intensifying storms.',
      ],
      k: ['Cloud droplets are ~0.01 mm; a raindrop is ~2 mm — rain requires a 100× growth trick', 'Cold-cloud ice-crystal process makes most mid-latitude rain and all snow', 'Droplets form on particles: dust, salt, smoke — pure air barely condenses'],
      q: { s: 'Why doesn’t a visible cloud just fall down as rain immediately?', o: ['Its drops are too small for gravity to beat the updraft', 'The Sun evaporates it faster than it falls', 'Static electricity holds the drops up'], a: 0, e: 'Micrometre-scale droplets sink almost imperceptibly slowly; rising air easily holds them up. Only merged/grown drops become heavy enough to fall as rain.' } },
    { s: 'thunder-lightning', t: 'Thunderstorms and Lightning', mn: 8,
      sum: 'How a cloud charges, why thunder claps, and the real safety rules.',
      p: [
        'Inside a big cumulonimbus, supercooled water, ice and graupel (soft hail) collide in violent updrafts, and those collisions separate charge: lighter ice carries positive charge to the top, heavier graupel drags negative charge to the middle and base. The ground below becomes positively charged by induction. When the field grows strong enough — millions of volts per metre in places — a faint stepped leader of ionised air probes down from cloud in stages, and a streamer rises from the ground to meet it. Contact closes the circuit, and the return stroke — the flash you actually see — races back up the channel at around a third of light speed.',
        'The channel briefly reaches about 30,000 °C, roughly five times the Sun’s surface, and the air around it detonates outward in a shock wave that decays into the sound we call thunder. Light and sound travel the same path at wildly different speeds, which is the counting trick: three seconds per kilometre (or five per mile) between flash and bang gives the distance. If the gap shrinks as storms pass, the storm is approaching you.',
        'Safety facts that survive the folklore: lightning does strike the same place twice — the Empire State Building is hit dozens of times a year; rubber-soled shoes and car bodies are safe because of the metal shell’s Faraday-cage path around occupants, not because rubber insulates anything at lightning voltages; and the “30/30 rule” (go indoors if thunder follows a flash within 30 seconds, stay 30 minutes after the last thunder) exists because lightning can kill far from rain — up to 10–15 kilometres from a storm’s edge in what people call “bolt from the blue”. The only short answer: when thunder roars, go indoors.',
      ],
      k: ['Charge builds by ice colliding with soft hail inside the updraft', 'Thunder is a shock wave from air heated near 30,000 °C in a flash', 'Count 3 seconds per km from flash to bang; take cover 30 min after last thunder'],
      q: { s: 'A flash and the bang arrive 9 seconds apart. The storm is about:', o: ['1 km away', '3 km away', '9 km away'], a: 1, e: 'Sound crawls at ~343 m/s while light is effectively instant: about 3 seconds per kilometre, so 9 s ≈ 3 km.' } },
    { s: 'tropical-cyclones', t: 'Hurricanes, Typhoons, Cyclones', mn: 8,
      sum: 'One storm, three names — and how warm water builds the deadliest weather machines.',
      p: [
        'A hurricane, a typhoon and a cyclone are the same animal born in different oceans: a tropical cyclone, named by basin — Atlantic and north-east Pacific (hurricane), north-west Pacific (typhoon), Indian Ocean and south Pacific (cyclone). The recipe is short: sea surface at least around 26.5 °C through a deep layer, moist unstable air, weak wind shear so the stack is not torn apart, and enough planetary spin to start rotation. That last condition explains something people ask every season: a tropical cyclone can never form right on the equator, where the Coriolis twist is zero — and it can never cross the equator from one hemisphere to the other on its own.',
        'The engine is heat, not wind. A mature storm lifts tens of thousands of tonnes of water vapour per second and converts released condensation heat into wind with an efficiency a power plant would envy, exporting the rest as rain. A single Atlantic hurricane can release heat at a rate around twice the global human energy consumption — that is why “category” scales fast: Saffir–Simpson Category 1 begins at 119 km/h (74 mph) winds, and Category 5 from 252 km/h. But category is only wind. The deadliest hazard in a landfalling cyclone is storm surge — the dome of seawater pushed ashore — which has killed far more people than the winds in nearly every recorded disaster, because nearly everyone drowning had no idea they were in a flood.',
        'The Pacific side adds two names to the year: typhoon season peaks into late summer and autumn, and warm-season storms in the west are typically stronger and bigger than Atlantic cousins because the warm pool there is deeper. Climate change does not create cyclones — it loads the dice: warmer seas mean more moisture and energy, storms that intensify faster, and slower forward motion that dumps catastrophic rain totals on one spot.',
      ],
      k: ['Hurricane/typhoon/cyclone differ only by ocean basin', 'Needs ~26.5 °C water + weak shear + planetary spin — none on the equator', 'Storm surge, not wind, is the historical body count driver'],
      q: { s: 'Why can’t a hurricane form at the exact equator?', o: ['Water is too warm there', 'The Coriolis effect that spins inflowing air is zero there', 'Trade winds blow too strongly'], a: 1, e: 'Cyclonic rotation needs planetary spin; the Coriolis force vanishes at the equator, so air spirals in without developing the circulation that organises a storm.' } },
    { s: 'elnino-nina', t: 'El Niño and La Niña', mn: 7,
      sum: 'The Pacific’s slow heartbeat that moves rain, drought and prices worldwide.',
      p: [
        'Under the trade winds, the tropical Pacific normally piles warm water in the west — around Indonesia — and cold water upwells off Peru. El Niño is the loosening of that setup: trades weaken, warm water sloshes east, and rain follows it. La Niña is the opposite extreme — trades tighten, the warm pool heaps even farther west, and upwelling chills the central Pacific. The two states plus a neutral phase make up ENSO, the El Niño–Southern Oscillation: not a cycle with a timetable but an irregular internal rhythm of the ocean–atmosphere system, switching roughly every two to seven years, each event lasting nine to twelve months.',
        'Because that warm pool is the planet’s largest heat engine, moving it rearranges rainfall across the globe through atmospheric teleconnections. During El Niño: southern US and Peru get wetter, Australia and Indonesia drier and fire-prone, Atlantic hurricane development gets sheared down. During La Niña the pattern often reverses: Australian and Southeast Asian floods, Atlantic hurricane seasons that run hot. The names are literal seasons — “the Christ child” because Peruvian fishers noticed the warm water most often around Christmas.',
        'The economics are real: ENSO phases show up in palm oil, rice and coffee prices, in hydropower reservoirs, in malaria season length. Forecasters watch a buoy array across the equatorial Pacific (the TAO network) plus satellite sea-surface temperature to call the phase months ahead — some of the most valuable weather predictions on Earth are made by people watching the middle of an ocean.',
      ],
      k: ['ENSO = the Pacific warm pool rocking east–west on an irregular 2–7 year rhythm', 'El Niño dries Australia/Indonesia, wets Peru/Southern US, suppresses Atlantic hurricanes', 'The phase swings commodity prices, fires and hurricane seasons worldwide'],
      q: { s: 'Which is generally true during a strong El Niño?', o: ['Atlantic hurricane season gets worse', 'Australia and Indonesia face drier conditions', 'Peru’s coast becomes drought-stricken'], a: 1, e: 'El Niño shifts rain east: Peru and the southern US get wetter, while the usual west-Pacific rain engine weakens — Australia and Indonesia run drier. Atlantic hurricanes are sheared down, not up.' } },
  ],
  earth: [
    { s: 'plate-tectonics', t: 'The Ground Is a Puzzle', mn: 8,
      sum: 'Continents float on slow convection, and their seams are where the ground breaks.',
      p: [
        'Earth’s rigid outer shell is broken like an eggshell into a dozen big and several small plates, each carrying a continent or an ocean floor — or both. Beneath, the hot mantle creeps in convection at fingernail speed, a few centimetres a year, and the plates ride it. Africa’s east is splitting (the East African Rift, future new ocean), the Atlantic is widening about 2.5 cm a year at its mid-ocean ridge, and the Pacific is shrinking because its edges are being consumed at trenches faster than new floor forms.',
        'Where plates meet is where geology happens. They can slide past each other (California’s San Andreas), collide and crumple upward (the Himalaya, still rising centimetres a year as India drives into Asia), or one can dive beneath the other (subduction — the Andes, Japan, and most of the world’s explosive volcanoes). The famous “Ring of Fire” around the Pacific is simply the longest chain of these subduction seams, and about 80–90% of the world’s large earthquakes occur along it — the planet’s most honest map label.',
        'The idea is younger than you would expect: continents proposed to have drifted as recently as 1912 (Alfred Wegener, widely mocked for lacking a mechanism), and the seafloor-spreading proof arrived only in the 1960s. Everything that fits now — matching coastlines, identical fossils on separated continents, the age stripes of ocean rock recording magnetic reversals — clicked into place in a single decade. Plate tectonics is biology’s evolution moment for Earth science: late, then sudden.',
      ],
      k: ['Plates move a few cm/year — fingernail growth speed — driven by mantle convection', 'The Himalaya still rise because India is colliding with Asia; the Pacific is shrinking', 'Roughly 80–90% of big earthquakes happen around the Pacific’s subduction edges'],
      q: { s: 'The Himalaya are still getting taller because:', o: ['Underground volcanism pumps them up', 'India is still driving north into Asia', 'Erosion of other ranges shifts weight'], a: 1, e: 'The Indian plate keeps converging with Eurasia at ~5 cm/yr; with nowhere to subduct cleanly, the crust crumples upward — the range grows by millimetres annually.' } },
    { s: 'volcanoes', t: 'Volcanoes: Three Places, Two Personalities', mn: 8,
      sum: 'Why some volcanoes glow politely and others end civilisations.',
      p: [
        'Almost all volcanoes sit in one of three settings: where plates split apart (mid-ocean ridges and continental rifts), where one plate sinks beneath another (subduction zones — the Pacific Ring), and where a deep mantle plume burns through the middle of a plate (hotspots — Hawaii, Iceland, Yellowstone). A fourth fact dominates the statistics: most volcanoes are under the sea, and most eruptions on Earth are unnoticed submarine ones building new crust.',
        'Temperament is chemistry. Runny basaltic lava, low in gas, oozes and fountains: Hawaii’s Kīlauea has erupted continuously for decades with lava lakes and rivers that move slower than a walking human — spectacular, mostly avoidable. Thick, gas-charged magma from subduction zones is another animal: it shatters itself apart in explosive blasts of ash and pumice, and collapses down its flanks as pyroclastic flows — superheated avalanches of gas and rock travelling over 100 km/h at several hundred degrees, which is what destroyed Pompeii and buried Montserrat’s capital in 1995. Lava rarely kills whole cities; flows, ash, lahars (mud rivers down volcano gullies) and gas do.',
        'The global cooling exceptions are real but rare: only truly colossal explosive eruptions inject enough sulphur gas into the stratosphere to shade the planet for a year or two. Tambora in 1815 made 1816 “the year without a summer”; Pinatubo in 1991 cooled Earth about half a degree for a year and was the first big eruption whose climate effect scientists predicted and measured with modern instruments. Most eruptions are far too small for that — and far too dangerous up close, which is where the vigilance belongs.',
      ],
      k: ['Volcanoes occur at splitting plates, sinking plates and deep hotspots — mostly undersea', 'Fluid lava fountains vs thick explosive magma: the difference is gas and stickiness', 'The killers are pyroclastic flows, lahars, ash and gas — not crawling lava'],
      q: { s: 'Why are subduction-zone volcanoes usually more explosive than Hawaiian ones?', o: ['They are hotter', 'Their magma is thicker and gas-rich, so pressure shatters it', 'They sit closer to the equator'], a: 1, e: 'Water-rich, viscous magma traps gases until they burst violently. Basaltic magma like Hawaii’s is thin and degasses gently — fountains, not blasts.' } },
    { s: 'tsunamis', t: 'Tsunamis: The Fastest Thinkable Danger', mn: 7,
      sum: 'Not a wave — a moving wall of the whole ocean, and 30 minutes can save everything.',
      p: [
        'A storm wave moves only water near the surface; a tsunami moves the entire water column at once. An undersea earthquake that vertically faults the seafloor displaces a slab of ocean kilometres high and hundreds of kilometres wide, and gravity flattens the bump by flinging it outward at speeds near 700–800 km/h — a jetliner’s cruise, in water only 4 km deep. In the open ocean the tsunami is almost invisible: a gentle slope tens of centimetres high spread over 100–200 km of wavelength. Nobody feels it from a ship.',
        'Danger builds as it shoals: the wave drags on the bottom, slows to tens of km/h, and its energy compresses into a wall metres to tens of metres tall. A tsunami is also a series of waves arriving minutes apart — the first is often not the biggest, and the sea pulling strangely far out from the shore is a classic premonition of surge. The fatal mistake is “wait and see”, because the natural warning signs are the warning.',
        'Physical signs that demand immediate movement to high ground (20–30 m or 2–3 km inland): a strong or long-shaking earthquake near the coast, an unusual roar from the sea, or sudden drain-out of the surf. The 2004 Indian Ocean disaster killed around 230,000 people; the one village famously spared, on Indonesia’s Simeulue island, survived because oral history had taught its people to run to the hills when the sea withdrew — after the 1907 tsunami the elders had turned into story. Warning systems exist now across the Pacific and Indian oceans; they bought their first test in 1960 after the Chile earthquake’s tsunami crossed an ocean unannounced and killed in Japan hours later.',
      ],
      k: ['Tsunami speed in deep ocean ≈ 800 km/h; wavelength 100+ km — invisible at sea', 'It steepens into a wall only near shore; the “wave” is actually a series', 'Strong coastal shaking or a draining sea = run uphill immediately, no watching'],
      q: { s: 'Why is a tsunami harmless for ships in the open ocean?', o: ['It is blocked by currents', 'Its energy is spread over 100+ km — barely a bump', 'It only travels in shallow water'], a: 1, e: 'Far from shore a tsunami is a long, low slope; nothing steep to break. It becomes a wall only where the seabed squeezes the wave tall.' } },
    { s: 'deep-time-rocks', t: 'Deep Time and the Rock Cycle', mn: 7,
      sum: 'Earth is 4.54 billion years old — and humans appear in the last seconds.',
      p: [
        'Geologists sort rock three ways by origin, not look. Igneous rock froze from molten material — every ocean floor, most of the crust, and the basalt of Hawaii. Sedimentary rock is reassembled debris or precipitate: sandstone from sand, limestone largely from shells and reef debris, shale from mud — the library layer-cake where fossils and Earth’s past climate live. Metamorphic rock is either of the first two, cooked and squeezed into something new underground — marble from limestone, slate from shale. The cycle runs because plate tectonics keeps recycling crust into magma and back up again, which is why Earth’s oldest intact rocks are about 4 billion years and meteorites (never recycled) are what actually give the planet’s 4.54-billion-year age.',
        'The scale of deep time is the hard part to internalise. Compress Earth’s whole history into a single calendar year: the planet forms on 1 January, the first unmistakable life appears somewhere around March, complex cells with nuclei arrive in late October, the Cambrian explosion of animal bodies bursts open around 17 December, the dinosaurs’ reign ends about Christmas Day — and behaviourally modern humans show up in the last hour or so of 31 December. Everything you have ever heard about as “ancient history”, pyramids included, is the final seconds after midnight of the last New Year.',
        'Reading it is like reading tree rings: stratigraphy — older layers below younger — plus absolute dating by radioactive decay (uranium to lead, carbon-14 for recent organics). The two methods agree across oceans and continents, which is why “4.54 billion years” is not a guess held loosely but a number checked by independent clocks that refuse to disagree.',
      ],
      k: ['Three rock origins: frozen melt, reassembled debris, and cooked-and-squeezed redo', 'Earth’s age (4.54 Ga) comes from meteorites, since its oldest crust is recycled', 'On the year-clock: all of human history fits in the last minutes of 31 December'],
      q: { s: 'A marble countertop began life as:', o: ['Molten lava', 'Limestone, recrystallised under heat and pressure', 'Volcanic ash cemented together'], a: 1, e: 'Marble is metamorphic limestone — the shells and carbonate mud of an ancient sea, cooked into interlocking crystals without ever melting.' } },
    { s: 'freshwater', t: 'Freshwater: The Thin Skin of Water', mn: 7,
      sum: 'Most of the planet is stone-hard salt; the drinkable slice is thinner than it looks.',
      p: [
        'Of all water on Earth, roughly 97% is salty ocean. Of the ~2.5% fresh, about two-thirds is locked in ice sheets and glaciers and much of the rest lies underground, so river and lake water — the visible, refillable, life-supporting part that most ecosystems and our taps depend on — is well under 1% of one percent of the total. A glass of salt water out of every litre of Earth’s water, with a teaspoon of the fresh portion drinkable, is the honest proportion.',
        'What moves that teaspoon is the water cycle, and its reservoirs differ wildly in how long they hold: a water molecule spends about a week in the atmosphere as cloud and rain, months to years in rivers and soil, centuries in a deep lake or a temperate groundwater pool, and tens of thousands of years in an ice sheet or a fossil aquifer. Groundwater is the quiet savings account: India and the US Great Plains and much of the Middle East irrigate largely on aquifers, some being pumped faster than rain refills them — Ogallala in the US, the North China Plain, the Arabian fossil water being spent within decades.',
        'The human pressure is now measurable: the UN counts roughly two billion people living with water stress, and agriculture withdraws about seven in ten freshwater litres. But “water shortage” is usually management, not physics: the cycle returns the same water it always has — clean, cold, and in the right place is an engineering, pollution and pricing problem, not a shrinking-ocean problem. Reuse at Singapore scale proves it.',
      ],
      k: ['Fresh water is ~2.5% of Earth’s water; usable surface store is a fraction of that', 'Atmosphere refills in ~a week, glaciers in ~80,000-year slow turnover; groundwater varies', 'Most “water crises” are about timing, cleaning and routing — not destroying the cycle'],
      q: { s: 'Which holds water in fast circulation — turning over roughly within weeks?', o: ['Deep glaciers', 'The atmosphere (as vapour and cloud)', 'Fossil aquifers'], a: 1, e: 'Water cycles through the atmosphere on the order of 9–10 days; glaciers and fossil groundwater store for thousands of years.' } },
  ],
  air: [
    { s: 'atmosphere-layers', t: 'The Atmosphere Has Floors', mn: 7,
      sum: '90% of the air you breathe sits below your cruising altitude — the sky is a thin skin.',
      p: [
        'Half the mass of the atmosphere sits below just 5.5 kilometres, and 90% below about 16 km: the blanket of air is, relative to Earth’s size, thinner than skin on an apple. The first floor, the troposphere, holds almost all weather and water vapour because almost all the mass and the heat engine (the surface) live there. Above it, temperature does something counter-intuitive: it stops falling and rises, because ozone is busy absorbing sunlight and warming the layer — this stable, warm floor is the stratosphere, home of jets’ smooth rides and of the protective ozone layer.',
        'Higher still the air grows cold again (mesosphere, the coldest place on Earth, where meteors burn) and then astronomically hot in the thermosphere — thousands of degrees, yet a thermometer there would freeze, because there is almost no matter to touch it with: “temperature” is average energy per molecule, not a feeling, and the exosphere simply fades into space around the Kármán line, the conventional 100-km edge of space. Astronauts do not float because there is no gravity — Earth’s pull at the ISS is still about 90% as strong as on the ground — they float because they are perpetually falling around the planet.',
        'Everything that keeps you alive sits in the bottom 16 km of that stack: weather, ozone shielding, jets. And that is exactly why what we put into the air matters so directly: the atmosphere is thin, and it mixes globally in a year or two, which turns a local emission into a planetary ingredient.',
      ],
      k: ['Half the atmosphere’s mass lies below 5.5 km — the sky is a skin, not a sea', 'Stratosphere warms with height because ozone absorbs UV — stable air, smooth flight', 'Astronauts fall, not float away from gravity: 90% of surface gravity reaches the ISS'],
      q: { s: 'Why do the ISS astronauts feel weightless?', o: ['There is no gravity in space', 'They and the station fall around Earth together', 'Solar wind pushes them up'], a: 1, e: 'Gravity at 400 km is nearly as strong as on the surface; the station moves sideways fast enough to keep missing Earth — continuous free-fall reads as floating.' } },
    { s: 'aqi-explained', t: 'What the AQI Number Means', mn: 7,
      sum: 'PM2.5, the 0–500 scale, and why your city’s number is a model estimate.',
      p: [
        'Air quality indices do one job: convert raw pollutant concentrations into a single number where higher is worse. The US AQI runs 0–500 in six bands — 0–50 good, up to “hazardous” above 300 — computed separately for several pollutants, and the headline number is whichever pollutant hurts most, usually the driver of the day. It is a public-health alarm clock, deliberately coarse enough to act on without a degree in chemistry.',
        'The pollutant that matters most for longevity is PM2.5: particles under 2.5 micrometres — around 30 of them side by side across a human hair. At that size, inhaled particles bypass every defence your airways have, lodge in deep lung tissue and cross into blood. Sources: combustion — vehicles, cookfires, cigarettes, crop burning, coal — not pollen, which is far bigger. The World Health Organization’s 2021 guideline for annual average exposure is 5 µg/m³, halving its previous target because the evidence kept hardening; much of the world’s population lives above 35.',
        'Understand what a live ranking like our /udara page is measuring: satellite- and chemistry-transport-model estimates at city coordinates (the Copernicus CAMS service, via Open-Meteo), refreshed hourly. Models are brilliant for regional comparison and wrong for your street, where a busy road or a cooking fire can triple the local number. Treat the city figure like a fever chart, not a diagnosis.',
      ],
      k: ['AQI = higher-is-worse alarm from several pollutants; worst pollutant sets the headline', 'PM2.5 (≤2.5 µm) enters the bloodstream past all airway filters — the deadliest scale of dirt', 'Model city numbers rank regions well; a street can differ several-fold'],
      q: { s: 'A US AQI of 170 means:', o: ['Mild — fine for everyone', 'Unhealthy: everyone starts to feel it, sensitive groups clearly', 'Hazardous — stay indoors entirely'], a: 1, e: '151–200 is the “Unhealthy” band: effects for sensitive groups are already significant at 101–150, and 151+ affects the general population too. “Hazardous” only begins above 300.' } },
    { s: 'greenhouse-effect', t: 'The Greenhouse Effect, Honestly', mn: 8,
      sum: 'Why 0.04% of the air decides the planet’s temperature.',
      p: [
        'The standard metaphor misleads on one point: the atmosphere is not trapping heat like glass in a garden greenhouse (real greenhouses mostly work by blocking rising air). The honest version: the Sun sends in visible light, Earth’s surface warms and re-emits that energy as infrared, and certain gases — water vapour, carbon dioxide, methane, nitrous oxide — absorb and re-emit infrared, slowing its escape to space. With the natural blanket, Earth’s average surface sits near +15 °C instead of about −18 °C. Life exists in the difference.',
        'The “CO₂ is only 0.04% so it can’t matter” objection fails on measurement, not rhetoric: remove the blanket entirely and our average temperature would drop by tens of degrees. Thin dials matter when they sit on a thermostat. And CO₂ is the dial humans control: water vapour, the biggest natural absorber, responds to temperature but doesn’t initiate change — warm air holds more moisture, roughly 7% per extra degree, which amplifies whatever CO₂ starts. That amplification is why a small forcing moves several degrees, not fractions.',
        'Since 1850 the CO₂ concentration has climbed from around 280 to over 420 ppm — the 426.7 ppm scale visible live on our /udara/carbon page — and the fingerprint is checkable in three independent places: the isotopic weight of the added carbon (fossil carbon lacks certain isotopes that living and atmospheric carbon carry), the fact that the upper atmosphere cools while the lower warms (trapping signature, not a brighter Sun), and the oceans absorbing both carbon and heat. Three different measurements, one story.',
      ],
      k: ['Greenhouse gases slow infrared escape; without them Earth averages about −18 °C', 'Water vapour amplifies (≈7% more moisture per °C) but CO₂ is the trigger we control', 'CO₂ 280→420+ ppm: fingerprint confirmed by isotopes, cooling upper air, ocean uptake'],
      q: { s: 'Why is water vapour not the main driver of current warming?', o: ['It does not absorb infrared', 'It responds to temperature — it amplifies rather than starts the change', 'Rain washes it out within days'], a: 1, e: 'Water vapour is the largest natural greenhouse gas, but its amount is set by air temperature. Humans are changing the CO₂ dial that sets the thermostat; the moisture feedback follows.' } },
    { s: 'ozone-layer', t: 'The Ozone Comeback Story', mn: 7,
      sum: 'We broke the UV shield, then fixed the treaty — proof the planet can heal.',
      p: [
        'Ozone (O₃) is oxygen’s short-lived cousin. High in the stratosphere, a thin concentration a few parts per million absorbs the Sun’s harmful UV-B — enough to protect land life, and the amount in the entire layer is so little that if compressed to tropospheric density it would be a few millimetres thick. Fragile, essential, invisible: the layer forms where UV splits O₂ and freed atoms attach to more O₂, continuously made and destroyed.',
        'In 1974 two chemists proposed that a family of human-made gases — chlorofluorocarbons, inert, cheap, non-toxic, perfect refrigerants — were destroying that layer: CFCs drift up intact, UV shreds them over the pole, and each released chlorine atom catalytically destroys thousands of ozone molecules before it is removed. The 1985 discovery of the Antarctic ozone hole proved them right faster than anyone expected. By the late 1980s, measurements showed the hole deepening each spring and ozone thinning globally.',
        'The response is the template for doing planetary problems well: the 1987 Montreal Protocol phased CFCs out with binding dates, differentiated duties for rich and poor economies, and became the first treaty ratified by every country on Earth. Production of the worst ozone killers is essentially zero now, and monitored recovery is real — models and observations project the Antarctic hole closing around mid-century, decades after the chemistry predicted a fix would even be attempted. One caveat for honesty: the gases that replaced CFCs (HFCs) are harmless to ozone but potent greenhouse gases, which is why the 2016 Kigali Amendment extended the same machinery to them.',
      ],
      k: ['Stratospheric ozone is a thin UV-B shield — a few mm thick if squeezed to sea-level air', 'One CFC-released chlorine atom destroys ~1,000s of ozone molecules before removal', 'Montreal Protocol: universally ratified, working — recovery projected by ~2050-2060s'],
      q: { s: 'Why did CFCs reach the stratosphere intact?', o: ['They are heavier than air', 'They were designed to be chemically inert — nothing below destroyed them', 'Volcanoes pumped them up'], a: 1, e: 'Their stability was the sales feature: no reactions in the lower atmosphere meant the only thing that could break them down was strong UV — found above the ozone layer.' } },
    { s: 'indoor-co2', t: 'The CO₂ in Your Room', mn: 6,
      sum: 'Why classrooms get sleepy by 10 a.m., and the oldest fix works.',
      p: [
        'Outdoor air in 2026 carries roughly 420–430 ppm CO₂. A room fills with the same number plus exhaled breath: a person breathes out air at about 40,000 ppm, and every occupant adds about half a litre of it per breath. Close enough doors in a populated room and levels climb through 1,000 — the conventional “adequate ventilation” mark — to 2,000 and beyond by late morning in schoolrooms worldwide; measured classroom peaks exceed 3,000 ppm routinely when windows stay shut. The occupants notice nothing at 800 and feel the room at 2,000.',
        'Study after study of offices and schools finds measurable costs in that stale band: slower response times, reduced concentrated arithmetic, morning drowsiness attributed to the lesson rather than the air. A few parts per million of a gas aren’t toxic at these levels — the effect is subtle physiology we do not fully understand, which is exactly why cheap prevention makes sense. The same sensors that track outdoor AQI track this for under the price of a meal.',
        'The fixes are old and new: open a cross-breeze (air exchange is the whole game), exhaust at the source (kitchen and bathroom fans actually used), and in polluted-climate buildings, filtered mechanical ventilation with heat recovery. Plants, contrary to every office poster, clean a room’s CO₂ negligibly — the photosynthetic sink is tiny compared with one sleeping human’s output; ventilation beats chlorophyll for this specific job every time.',
      ],
      k: ['Exhaled breath is ~4% CO₂; closed rooms stack past 2,000 ppm by midday', '1,000–2,000 ppm measurably slows focus — the drowsiness is the room, not the lesson', 'Cross-ventilation fixes it cheapest; houseplants are irrelevant for CO₂'],
      q: { s: 'A classroom CO₂ reading of 2,400 ppm mostly indicates:', o: ['A toxic gas leak', 'Poor ventilation with human occupants', 'Outdoor pollution seeping in'], a: 1, e: 'Indoor CO₂ this high is exhaled breath accumulating because fresh air exchange is too low — not a hazard like carbon monoxide, but a proven freshness and focus problem.' } },
  ],
  body: [
    { s: 'heart-circulation', t: 'The Pumps in Your Chest', mn: 8,
      sum: '100,000 beats a day, two circuits, and the pressure numbers that mean.',
      p: [
        'Your heart is two pumps sharing a wall: the right side sends spent blood through the lungs to reload oxygen (low pressure — lungs are delicate), the left side drives that blood to everything else at many times the pressure. It moves about five litres a minute at rest, roughly 7,500 litres a day, and beats close to 100,000 times a day — around 2.5 billion in an average lifetime — starting before you were born, from a single looping tube squeezed by its own pacemaker cluster, the sinus node, which fires the electrical wave every beat. That wave is what an ECG reads: the muscle is electrically driven, chemically tuned and mechanically executed.',
        'Blood pressure numbers are push and rest: 120/80 mmHg means the artery peaks at 120 during a squeeze and never falls below 80 between beats. Sustained high pressure is dangerous not for the number itself but what it does — it wounds artery walls, and those wounds are where cholesterol lodges: atherosclerosis is largely an injury-repair response at the sites where pressure and turbulence damage the lining. The vicious loop is real: stiffer arteries raise the top number, which stiffens them further.',
        'The system’s engineering elegance shows in capillaries: blood-vessel walls one cell thick, so narrow that red cells fold single-file and spend under a second in contact with tissue, delivering oxygen via haemoglobin — the iron-containing molecule that grips oxygen loosely and releases it where acidity and CO₂ are high, precisely where working muscle needs it. Resting muscles get about a fifth of output; the brain alone, at 2% of body mass, bills about 20% of the energy — an expensive tenant the plumbing exists to serve.',
      ],
      k: ['Right heart feeds lungs at low pressure; left feeds the body at high — two pumps, one wall', 'Blood pressure = squeeze peak and between-beat floor; damage starts at wounded linings', 'Haemoglobin unloads oxygen where CO₂/acidity run high — working muscle gets the most'],
      q: { s: 'The “80” in a 120/80 reading is:', o: ['The vein pressure', 'The artery pressure between beats', 'The lung circuit’s peak'], a: 1, e: 'Diastolic pressure: the lowest arterial pressure, reached when the heart relaxes and arteries keep pushing blood forward between squeezes.' } },
    { s: 'lungs-breathing', t: 'Lungs: The Quiet Surface', mn: 7,
      sum: 'A folded 70-square-metres of tissue that works because you stop thinking about it.',
      p: [
        'Breathing is inflation by vacuum: the diaphragm — a dome under your lungs — contracts downward, the ribcage spreads, chest pressure drops below atmospheric, and the outside air simply shoves itself in. No muscle “pulls air”. Exhaling at rest is mostly elastic recoil: your lungs are stretched-rubber springs that snap back. Rest rate is 12–20 breaths a day-and-night without a single decision, run automatically by a brainstem rhythm generator that mostly listens to one signal: CO₂ levels. Surprisingly, the urge to breathe comes from carbon dioxide waste, not oxygen shortage.',
        'Inside, the airway tree branches some 23 times until tubes are too thin to blow air through, and gas moves by diffusion alone across the final stop: the alveoli, several hundred million tiny sacs whose folded total exchange surface is commonly estimated at 50–100 square metres — the floor area of a small flat, packed into your chest. Walls one cell thick touching capillary walls one cell thick: oxygen crosses both in under a second. The surface stays wet (otherwise the sacs collapse like wet plastic bags) and is lined with a detergent — surfactant — that keeps the water from pinching them shut; premature babies die without it, and giving it is one of medicine’s quiet miracles.',
        'The exhaled gas is the receipt: about 16% oxygen (down from 21%), 4% CO₂ (up from 0.04%), saturated with water — the visible cloud of a cold-morning breath. The leftovers matter: rescue breathing works precisely because your waste breath still holds useful oxygen, and every litre of exhaled air is carrying away metabolised water and the spent carbon of the food you burned.',
      ],
      k: ['You inhale by lowering pressure — muscles expand the box; air pushes itself in', 'The brain drives breathing mainly from CO₂, not oxygen', 'Alveolar exchange area ≈ a small apartment’s floor, folded into a fist-sized pair'],
      q: { s: 'The strongest everyday trigger to breathe harder is:', o: ['Falling blood oxygen', 'Rising blood CO₂ and the acidity it causes', 'Falling blood sugar'], a: 1, e: 'Central chemoreceptors watch CO₂-driven pH; a rising level of the waste gas — not the oxygen drop — is what drives the deep urgent breath after sprinting.' } },
    { s: 'brain-nerves', t: 'The Brain: Three Pounds of Wiring', mn: 8,
      sum: '86 billion cells talking in electricity and chemistry, and why it rewire itself.',
      p: [
        'The modern count for human cerebral neurons is roughly 86 billion, each connecting with thousands of others — a wiring diagram whose synapse count exceeds a hundred trillion. Information moves as electricity along the axon, an impulse near 100 millivolts travelling anywhere from a slow 1 m/s to over 100 m/s depending on myelin, the fatty insulation wrapped around fast lines (the same insulation whose loss causes multiple sclerosis). At each junction the electrical trick becomes chemistry: a burst of molecules diffusing across a gap of 20 nanometres, caught by receptors that decide — fire or don’t.',
        'The cost is startling for its size: at about 2% of body mass, the brain bills around 20% of resting energy, mostly to run the ion pumps that reset every electrical firing — the brain is an expensive machine kept perpetually cocked. It is also fenced: the blood–brain barrier tightly controls what crosses from blood, keeping out many useful medicines as readily as toxins — which is why treating brain illness is pharmacology’s hardest real estate.',
        'Two properties turn the wiring into a life. Plasticity: connections that fire together strengthen, those unused are pruned — the reason childhood learning is cheap, adult skill is effortful, recovery after stroke is possible, and repeated practice physically rebuilds hardware. And the housekeeping nobody thought to look for: during deep sleep, the brain’s cells shrink slightly so fluid washes interstitial space, clearing metabolic debris including Alzheimer-linked proteins — the strongest current reason sleep is not a luxury but maintenance, booked nightly by every animal that has ever slept.',
      ],
      k: ['~86 billion neurons; signals are electrical along axons, chemical across synapses', 'Myelin is the insulation that makes fast thought fast — its loss breaks signalling', 'Deep sleep appears to be the brain’s dishwasher cycle — plasticity and cleaning are real'],
      q: { s: 'Learning a skill physically changes the brain mainly by:', o: ['Growing new skull capacity', 'Strengthening and insulating the circuits that fire repeatedly', 'Increasing neuron size uniformly'], a: 1, e: 'Practice strengthens specific synapses (long-term potentiation) and can add myelin to participating axons — change is local and use-dependent, not bulk growth.' } },
    { s: 'digestion-metabolism', t: 'Digestion: The Long Chemistry Bench', mn: 7,
      sum: 'A seven-metre workbench that turns bread into you, acid-washes invaders, and farms tenants.',
      p: [
        'Food is not fuel until chemistry breaks it to its parts, and the tract is a seven-to-nine-metre production line in three acts. The mouth mechanically preps and enzymatically starts starch; the stomach is the acid bath — hydrochloric acid at pH 1.5–3.5, strong enough to dissolve meat and kill most pathogens (a genuine immune front line), with a mucus-lined wall protecting the organ from digesting itself, and pepsin snipping proteins into fragments. Then the small intestine does the absorption: its lining folded into villi and microvilli giving a surface area estimated at tens of square metres, where digested sugars, amino acids and fats cross into blood or lymph, with bile — a detergent made by the liver, stored in the gallbladder — emulsifying fat so enzymes can act on it.',
        'The large intestine is water recovery plus a city: roughly 38 trillion bacteria — the microbiome, of the same order as our own cell count — ferment what you could not digest, manufacture vitamins (including a meaningful share of vitamin K), train and modulate immunity, and clearly communicate with the brain via vagus nerve and metabolites. Honest science on this frontier says “influences strongly”, not “controls mood”, and probiotic claims outpace evidence — but that antibiotics can reshape the flora, and that constipation is largely colon-water handling, is settled.',
        'Metabolism is the ledger after absorption: glucose for quick energy, fatty acids for storage and reserve, amino acids rebuilt into your own proteins. You continuously dismantle and rebuild most of your body — liver cells in weeks, red cells in 120 days, bone remodelled over years. “You are what you eat” is literally true in slow motion; the machinery re-assembles you from whatever you supply.',
      ],
      k: ['Stomach acid (pH 1.5–3.5) is digestion and a pathogen firewall at once', 'Nutrients cross the small intestine’s folded tens-of-m² surface; bile is fat soap', 'Your gut hosts ~38 trillion bacteria that ferment, vitamin-make and help train immunity'],
      q: { s: 'Bile, made by the liver, works by:', o: ['Acidifying food', 'Emulsifying fat into droplets enzymes can attack', 'Killing bacteria'], a: 1, e: 'Bile is a detergent that breaks fat into tiny droplets, hugely multiplying the surface where lipase enzymes can work. The acid and antimicrobial roles are the stomach’s.' } },
    { s: 'immunity-vaccines', t: 'Immunity: The Learning Army', mn: 8,
      sum: 'Two defence layers, and the 230-year-old trick that taught the second one.',
      p: [
        'The immune system is two tiers. Innate defences act immediately and generically: barriers (skin, acid, mucus), patrol cells that engulf anything marked foreign, and inflammation — the heat, swelling and pain are the sound of blood flow and repair crews arriving, not the enemy attacking. Adaptive defences are slower (days on first meeting) but specific: lymphocyte cells that, in effect, run a lottery — your body maintains millions of lymphocyte varieties with random receptor shapes, and when an infection matches one, that clone is found and expanded into an army tuned to exactly that pathogen, plus survivors that stay for decades: memory cells.',
        'Vaccination pre-plays that scene without the disease: it shows the adaptive system a safe piece of the pathogen (weakened or killed microbe, a purified protein fragment, or in mRNA platforms, coded instructions for a harmless protein piece) so the expansion and memory-building happen while there is no emergency. First variolation practices predate understanding; Edward Jenner’s 1796 cowpox experiment against smallpox started scientific vaccination two centuries before anyone could explain antibodies, and the world still executed the only human disease ever eradicated — smallpox, last natural case 1977 — using it. Modern platforms have cut the design time for a new vaccine candidate from years to days.',
        'Honest limits keep the field healthy: immunity from infection or vaccination can wane against recent variants (respiratory viruses repeatedly re-infect people), “herd immunity” works only for infections that don’t live in animal reservoirs, and the immune system’s occasional misfires — allergies, autoimmune disease — reveal how narrow the margin is between protection and self-attack. It is not a wall; it is a learning, adaptive force that trades speed against specificity and needs to be trained.',
      ],
      k: ['Innate immunity is instant and generic; adaptive is slow, specific and remembers', 'Vaccines are rehearsal: immune memory built without enduring the real infection', 'Smallpox (1980 declared eradicated) is proof the rehearsal principle works at species scale'],
      q: { s: 'An mRNA vaccine teaches immunity by:', o: ['Injecting weakened virus', 'Coding a harmless pathogen protein for the immune system to learn on', 'Boosting general white-cell counts'], a: 1, e: 'The mRNA carries instructions for one viral protein fragment; cells briefly make it, the adaptive system mounts memory against it, and no whole virus is ever involved.' } },
  ],
  life: [
    { s: 'photosynthesis', t: 'Photosynthesis: The Real Engine', mn: 7,
      sum: 'Sunlight turned into sugar and oxygen — the reaction that runs almost every food chain.',
      p: [
        'One line carries most life on Earth: carbon dioxide plus water, powered by light, becomes sugar plus oxygen. Inside chloroplasts, plants and algae capture sunlight with the green pigment chlorophyll and spend its energy tearing water apart — releasing the oxygen you are breathing as the exhaust of that step — then using the freed electrons to assemble carbon from CO₂ into sugars. Every calorie of food, and nearly every breath of oxygen, passed through this reaction at some point in its chain.',
        'The efficiency is humbling: crops convert only a few percent of the sunlight that hits them into stored chemical energy, and even that small share is why a field feeds a family while a bare rock feeds nothing. The slow-motion version of the same equation is also why every fossil fuel is ancient stored sunlight: coal, oil and gas are photosynthetic products from past ecosystems, buried before decay could spend them back.',
        'Who does the work matters for the air: ocean phytoplankton — microscopic drifting algae — contribute roughly half of global photosynthetic oxygen production, which is why the often-repeated claim that “the Amazon produces 20% of the world’s oxygen” misses the accounting: mature forests respire (burn back) nearly all the oxygen they make. The net gift to the atmosphere comes mostly from the sea and from young, growing wood.',
      ],
      k: ['CO₂ + water + light → sugar + oxygen: food and breathable air are one joint product', 'Only a few percent of incoming light becomes stored energy — yet that few percent runs the food chain', 'Marine phytoplankton do about half of all photosynthesis on the planet'],
      q: { s: 'The oxygen released by photosynthesis comes chemically from:', o: ['Carbon dioxide', 'Water', 'Sugar'], a: 1, e: 'Light energy splits water molecules; the oxygen a leaf releases traces back to H₂O, while CO₂ supplies the carbon of the sugar.' } },
    { s: 'pollination', t: 'Pollination: The Sex Life of Flowers', mn: 7,
      sum: 'Petals are advertising — and most of our food crops take the matchmaking.',
      p: [
        'Flowers cannot walk to a mate, so they outsourced: pollen must travel between them, and the travellers — bees, butterflies, beetles, bats, birds, flies — get paid in nectar or pollen itself. The entire flower industry is a marketing budget: colours tuned to pollinator vision (bees see ultraviolet landing patterns invisible to us), scents, landing-platform shapes, even timing to the hour. Around three-quarters of leading global food crops benefit from animal pollination to some degree for yield or quality; grasses (rice, wheat, maize) run on the cheaper wind strategy instead, which is why they are green and joyless.',
        'Honeybees are the famous employees but not the only ones, and not even always the best: for many crops, native solitary bees and bumblebees pollinate more effectively per visit, and bumblebees can buzz-pollinate — vibrating a flower to shake loose pollen that tomatoes and blueberries hide. Honeybees’ real global role is as managed, movable workforces; the wild pollinators do unpaid, irreplaceable background work through forests and farms.',
        'The pressures are measurable: habitat loss and pesticides thin wild pollinator populations, the varroa mite has reshaped managed beekeeping worldwide, and climate shifts can desynchronise a flower’s bloom from its pollinator’s season. The honest summary is that pollination is a system — matchmaking services matter more than any single species, and countries with diverse farms and hedgerows hold their natural insurance.',
      ],
      k: ['~75% of leading global food crops gain something from animal pollination; wind handles the grasses', 'Flower colours, UV patterns and scents are species-targeted advertising', 'Wild pollinators (not just honeybees) carry the unpaid backbone of the system'],
      q: { s: 'Why are grasses like wheat and rice plain-looking, wind-pollinated flowers?', o: ['They are ancient and unfinished', 'Expensive petal advertising is pointless when air does the delivery free', 'They reproduce by roots instead'], a: 1, e: 'Petals, scent and nectar are payments to animal vectors. Wind pollination trades precision for volume — cheap pollen clouds with no need to attract anyone.' } },
    { s: 'evolution', t: 'Evolution by Natural Selection', mn: 8,
      sum: 'The one idea that makes every species in the world suddenly sensible.',
      p: [
        'The argument takes three observations and one conclusion. Individuals in a population vary. Some of that variation is inherited. More offspring are produced than can survive, so variants that fit the local conditions leave, on average, more descendants — and the population’s makeup shifts toward those variants. That is natural selection, published by Darwin and Wallace in 1858, and it needs no goal, no direction and no designer — only differential survival and time. “Survival of the fittest” is Herbert Spencer’s slogan, and it misleads: fitness means offspring left behind, not strength.',
        'The evidence is not one museum of bones but several independent sciences agreeing: the fossil record now sequences major transitions (fish with wrists walking toward land, dinosaurs into birds, whales from wolf-sized land animals back to sea); DNA reads as one shared family tree, with the universal genetic code and the same genes reused in flies and humans; and comparative anatomy — the same five-fingered blueprint in a bat wing, a whale flipper and your hand — points to descent with modification. Most decisive for daily medicine: evolution runs under our eyes — every antibiotic resistance curve, every flu vaccine redesign and every pesticide-resistant insect is natural selection recorded this season.',
        'Two refinements stop bad summaries: evolution is not random — mutations arise randomly with respect to need, but selection is the opposite of random, preserving what works — and there is no ladder: life branched like a tree, so bacteria are not “primitive humans waiting to happen”; they are specialists of a different niche, as evolved as we are. Species still form continuously, islands are laboratories, and the modern synthesis since the 1930s welds the 1858 idea onto genes — the oldest framework in biology and still the one every new fact must fit.',
      ],
      k: ['Variation + inheritance + survivorship bias = populations shift, no planner required', 'Fossils, DNA, anatomy and real-time resistance all carry the same story independently', 'Mutations are random; selection is not — and life is a branching tree, not a ladder'],
      q: { s: 'Bacteria evolving antibiotic resistance in a hospital is best described as:', o: ['Bacteria deciding to adapt', 'Natural selection acting on random mutations, observed in real time', 'A side effect of drugs mutating DNA at will'], a: 1, e: 'Random heritable variants that survive the drug are left behind to reproduce — Darwin’s mechanism, running fast because bacteria reproduce fast.' } },
    { s: 'food-webs', t: 'Food Webs and Keystone Species', mn: 7,
      sum: 'Why the pyramid of energy leaves room for only a few tigers — and why some small species hold everything.',
      p: [
        'Energy flows, nutrients cycle. A plant captures a few percent of light; a herbivore eats the plant and keeps roughly a tenth of the energy it consumed — the rest is metabolism, movement and heat — and a predator gets about a tenth of that tenth. This ten-percent arithmetic is why food chains rarely exceed four or five links, why there are always more grass than gazelle than cheetah, and why eating lower on the chain feeds more people per hectare: the pyramid is not a policy, it is physics.',
        'Remove one link and the cascade reorganises the map. The textbook case: sea otters eat sea urchins, urchins eat kelp. Where otters were hunted out, urchin barrens scraped the kelp forests off the seabed — fish nurseries, storm buffers and carbon sinks lost together; where otters returned, the forest returned with them. Wolves in Yellowstone changed willow and stream banks after their reintroduction reduced overbrowsing. “Keystone species” names exactly this: not the biggest animal, but one whose removal rearranges far more than its own share.',
        'The quiet link everyone forgets is the disposal crew: fungi and decomposer bacteria close every loop, turning dead matter back into plant nutrient, and without them the world would be buried in its own leftovers. Dung beetles were imported to Australia precisely because European cattle dung sat undissolved for years — a living demonstration that even nutrient cycling needs appointed staff.',
      ],
      k: ['~90% of energy is lost at each trophic step — the reason top predators are always rare', 'Keystone effects are real: otters ↔ kelp, wolves ↔ Yellowstone streams', 'Decomposers recycle the atoms; ecosystems are loops of matter driven by one-way energy'],
      q: { s: 'Eating lower on the food chain feeds more people per hectare because:', o: ['Plants taste better', 'Each step up loses about nine-tenths of the energy', 'Predators need larger legal territories'], a: 1, e: 'Energy transfer between trophic levels runs near 10% efficiency, so every level “up” shrinks the carrying capacity by roughly an order of magnitude.' } },
    { s: 'migration', t: 'The Great Migrations', mn: 7,
      sum: 'Terns pole-to-pole, godwits nonstop for days — and the senses that navigate it.',
      p: [
        'Migration is the decision to let someone else have the good season: animals chase summer’s long daylight and food abundance across the planet twice a year. The Arctic tern rides the spring from Arctic breeding grounds to the Antarctic and back each year — tens of thousands of kilometres annually, seeing two summers, and living a life that adds up to the equivalent of several round trips to the Moon over its lifetime. The bar-tailed godwit flies nonstop from Alaska to New Zealand — over 11,000 km and about eleven days without landing, food or sleep, shrinking its own organs to travel light, a feat no human aircraft could copy at that efficiency.',
        'The navigation toolkit is genuinely multi-instrument: the sun by day with a body clock to correct for its movement; star patterns learned in youth (classic closed-sky experiments proved birds learn which stars circle the pole); evidence supports a magnetic sense tied to light-sensitive chemistry in the eye; plus landmarks, coastlines and inherited routes. Monarch butterflies solve the hardest version: individuals that have never made the trip migrate from Canada to a handful of Mexican groves their ancestors chose — the map is in the genes, corrected by selection each generation.',
        'Why bother: the payoff is energy math. Temperate summers offer almost endless daytime feeding for chicks; the tropics are stable but crowded and poor per capita. Migration trades enormous risk — exhaustion, storms, predators at stopover wetlands, windows and towers — against the richest feeding grounds on Earth. Populations of migratory species collapse precisely because every stopover matters: losing one wetland drains a continent’s birds.',
      ],
      k: ['Arctic terns log pole-to-pole round trips every year; godwits fly 11,000+ km nonstop', 'Birds navigate by sun, learned stars, magnetic sense and landmarks — several backups', 'Migration pays in summer food, and fails at every lost stopover site'],
      q: { s: 'Monarch butterflies reaching Mexico with no experienced guide is explained by:', o: ['They follow the wind randomly', 'An inherited, selection-tuned compass and internal clock', 'Older butterflies lead the young'], a: 1, e: 'Multi-generation migrants travel on genetic programming — a sun-compass clock plus evolved orientation; ancestors with better aim left more descendants.' } },
  ],
  numbers: [
    { s: 'percentages', t: 'Percentages Without Pain', mn: 6,
      sum: 'Move one decimal, halve it, add: the mental tricks sales and bills rely on.',
      p: [
        'Percent means “per hundred”, so 10% of anything is that thing shifted one decimal place left: 10% of 240 is 24. From there, 20% is double it, 5% is halve it, and 15% is the 10% plus half of the 5% — the tip-and-discount arithmetic that needs no calculator. Reversible percentages make the hard ones easy: 64% of 75 is painful, but percentages swap freely, so it is 75% of 64 — three quarters of 64, which is 48. Any percentage chain is just multiplication: a 20% cut followed by a 20% cut is 0.8 × 0.8 = 0.64, a 36% total reduction, not 40% — the shop applying “extra 20% off sale price” is counting on you to add percentages.',
        'The most abused distinction in public conversation is percent versus percentage point. When a tax goes from 5% to 8%, that is a 3-percentage-point rise but a 60% increase — both true, wildly different feelings, and both used as weapons in politics and advertising. Whenever someone quotes a percentage change, ask “from what base?”: a 300% increase on a base of two sales is still five sales.',
        'Percentages also hide in compounding, the quietest math in finance: 0.99 to the power 365 is about 0.03 — the “one percent worse every day for a year” meme is actually correct arithmetic — and 1.01^365 ≈ 37.8, the other direction. The same curve runs your loan, your subscription price rises and your savings; nothing in daily life grows in straight lines the way intuition expects.',
      ],
      k: ['10% = shift one decimal; build 15%, 20% and 5% from that one move', 'Percentage-point change ≠ percent change: 5%→8% is +3 points but +60%', 'Successive discounts multiply, never add: two 20% cuts total 36% off'],
      q: { s: 'A jacket is reduced 20%, then an extra 20% off the sale price. Total discount:', o: ['40%', '36%', '44%'], a: 1, e: '0.8 × 0.8 = 0.64 of the original price — you pay 64%, so 36% off. Adding percentages is the mental shortcut sales exploit.' } },
    { s: 'averages-lie', t: 'Averages and When They Lie', mn: 7,
      sum: 'Mean, median, and why “average salary” is the most misleading sentence online.',
      p: [
        'Three different “averages” answer different questions. The mean is the total divided by the count — the maths of sums and budgets. The median is the middle value once everyone is sorted — the person with exactly as many people above as below. The mode is the most common. With a tidy symmetric group they nearly coincide; with any long tail they split violently. Put four salaries of 30,000 and one of 1,000,000 in a room: the mean is 214,000 — true, and useless. The median is 30,000, and it is why statisticians insist on median income, median house price, median sleep: the middle survives billionaires.',
        'The mean only lies when you use it to describe “a typical member”; its real job is totals. “Average family has 2.4 children” sounds odd but predicts school enrolments perfectly, because average × families = children. Misuse arrives with per-capita statistics: “average sugar consumption per person: 40 kg/year” hides that some people drink none and others two soft drinks a day — an average is a distribution flattened into a number, and the interesting truth lives in the shape, not the flattening.',
        'Two habits immunise you: whenever you see “average”, ask “mean or median?”; whenever you see a difference between averages, ask about spread. Two towns with average temperature 20 °C can differ — one steady 19–21, one swinging 5–35 — and only the second needs a heavy coat. Always ask how many (a “58% satisfaction” from 12 respondents is noise wearing a percentage).',
      ],
      k: ['Median = middle of sorted data; it is immune to billionaires, the mean is not', 'Means describe totals correctly but “typical members” badly', 'Averages hide spread — same average, different coats'],
      q: { s: 'In a country where a few billionaires skew income, the figure describing a typical worker is the:', o: ['Mean income', 'Median income', 'Per-capita GDP'], a: 1, e: 'The median sits at the middle of the sorted list; extreme values change it barely at all, while the mean is dragged upward by every billionaire.' } },
    { s: 'compound-interest', t: 'Compound Interest: The Snowball', mn: 8,
      sum: 'Earning on your earnings — the Rule of 72 and why time beats amount.',
      p: [
        'Interest is money paid for the use of money; compound interest means last year’s interest starts earning too. At 10% a year, 100 becomes 110, then 121, then 133 — a curve that starts politely and ends steeply, which is why young savers underestimate it and old debtors are crushed by it. Credit cards are the negative side: 18% annual interest compounds monthly, so a balance carried all year grows about 20%, not 18% — the quoted rate systematically undersells the cost.',
        'The Rule of 72 is the one formula worth memorising: dividing 72 by an annual percentage gives roughly how long it takes to double. At 8%, about 9 years; at 24%, 3 years; at 6% inflation, your money halves in value in 12. Accurate enough for any conversation, no calculator, works in both directions — growth and erosion.',
        'The arithmetic of the real world: 100 a month at a typical long-run 7% return becomes roughly 122,000 after 30 years — only 36,000 of it yours, the rest growth-on-growth — while starting the same habit ten years later ends you near 58,000. Time is the dominant ingredient, not the amount; the snowball needs the hill more than the snow. Einstein’s apocryphal “greatest mathematical wonder” quote is unverified, but the exponential is not.',
      ],
      k: ['Compounding = interest earning interest; curves start flat, then vertical', 'Rule of 72: years to double ≈ 72 ÷ percent (works for inflation too)', 'Same monthly saving, started 10 years later, ends less than half as large'],
      q: { s: 'Money grows at 6% yearly. Roughly how long to double?', o: ['6 years', '12 years', '18 years'], a: 1, e: 'Rule of 72: 72 ÷ 6 = 12. (Exact: ln 2 / ln 1.06 ≈ 11.9 years — the rule is honest to within months.)' } },
    { s: 'probability-odds', t: 'Probability, Odds and the Gambler’s Trap', mn: 7,
      sum: 'Coins have no memory, rare things happen to someone constantly, and 23 strangers likely share a birthday.',
      p: [
        'Probability counts ways it can happen out of ways that could happen: a fair coin lands heads half the time. The trap is that humans feel probability as a debt — six heads in a row “makes tails due”. It does not: the coin has no memory, each flip is 50/50 again, and any specific 20-flip sequence (all heads included) is exactly as unlikely as any other. The streak feels special only because you noticed it after; that is the gambler’s fallacy, and it has emptied more pockets than any rigged machine.',
        'Two counter-intuitive results that train the intuition well. The birthday paradox: in a group of just 23 people, the chance two share a birthday exceeds 50% — not because anyone is unusual but because pairs grow quadratically (23 people hold 253 pairs). And the law of truly large numbers: with billions of events daily, “astonishing” coincidences — same lottery numbers drawn twice in a week somewhere on Earth — become inevitable; improbable things happen constantly, and the skill is estimating how many chances there were.',
        'Odds compare the two sides (“3 to 1 against” = 1 win in 4 = 25%), which is why gambling advertising loves them: 50-million-to-1 “odds” sounds like a long shot with a glimmer, while “0.000002% chance” is the same thing stated honestly. Expected value multiplies each outcome by its probability: a ticket with a 1-in-10-million top prize of 5 million and tiny other payouts is worth far less than a pound — every lottery is, collectively, a machine that takes in a billion and pays back less. Enjoy them as entertainment; never as a plan.',
      ],
      k: ['Independent events have no memory — streaks neither create nor repay debts', '~50% shared-birthday odds need only 23 people: pairs grow quadratically', 'Odds phrasing hides how small a chance is; expected value exposes it'],
      q: { s: 'A fair coin shows heads 8 times running. P(next flip is tails):', o: ['More than 50% — tails is due', 'Exactly 50%', 'Less than 50% — heads is hot'], a: 1, e: 'The coin does not know its own history. Eight heads is a surprising pattern in hindsight but never changes the next flip’s 50/50.' } },
    { s: 'inflation', t: 'Inflation: The Quiet Tax', mn: 7,
      sum: 'Why the same note buys less every year, and how to out-think the number.',
      p: [
        'Inflation is a rise in the general price level — equivalently, money losing purchasing power. It is measured with a basket: a fixed representative shopping list (food, rent, fuel, transport, haircuts) re-priced monthly, so the CPI answers “what would yesterday’s basket cost today”. Two people experience the same headline differently because personal baskets differ — if you rent and drive, energy and housing inflation are your real numbers, not the average’s.',
        'The arithmetic that matters is multiplication over years. At 3% a year, prices rise about 34% over a decade (1.03^10 ≈ 1.34) and double in about 24 years (Rule of 72 again). A salary that “stays the same” is being cut 3% annually; a 3% raise in a 3% year is flat. Modest rates compound into generational reshuffles: a pound at 2% for 50 years buys what 37 pence bought at the start — nobody voted for it and no line appears on a payslip, which is why inflation is called the tax without legislation.',
        'Why central banks target about 2% rather than zero: a small positive cushion lets real wages and prices adjust without pay cuts (people fight nominal cuts but accept being under-raise), avoids deflation’s trap (if prices fall, delaying purchases becomes rational, spending drains, debts grow in real terms — Japan’s lost decades in a sentence), and keeps rates above zero so there is room to cut them in a crisis. Savers’ honest conclusion: cash is the safe place to keep money you need soon and the costly place to keep money you need late.',
      ],
      k: ['CPI re-prices one shared basket; your personal inflation is your own basket', 'At 3%/yr: +34% prices in a decade, doubling in ~24 years — a flat salary shrinks', '2% targets exist to dodge deflation, the trap where waiting to buy starves the economy'],
      q: { s: 'Prices rise 4% a year. Your money halves in buying power in roughly:', o: ['8 years', '18 years', '25 years'], a: 1, e: 'Rule of 72: 72 ÷ 4 = 18. Inflation works both directions on the same curve — rates add, power subtracts.' } },
  ],
  internet: [
    { s: 'how-internet-works', t: 'How the Internet Actually Travels', mn: 7,
      sum: 'Packets, routers, DNS — and the fact that almost all of it runs under the sea.',
      p: [
        'Nothing on the internet is a wire from you to a website. Your message is chopped into packets — numbered chunks with a destination address — and each one is handed to the next router that is closer to the goal, free to take any path, reordered and reassembled at the far end. No central switchboard exists; the network is a mesh of millions of routers each consulting a table for “which neighbour is closest to that address”. This is why it survives damage: remove a link and traffic simply finds another way. A request and reply can cross the world in well under a second — light in fibre, plus the shuffle.',
        'Addresses come twice: numeric IP addresses (v4 still running out, IPv6 replacing) are what packets carry, but humans type names, so DNS — a global, cached, hierarchical phone book — turns tukuk.org into numbers before anything moves. The lookup itself is a chain of referrals starting from root servers, and it is why “the site is down but my friend in the next town can open it”: their cached address differed from yours while records updated.',
        'The physical truth surprises everyone: roughly 99% of intercontinental data — every video call, bank transfer and cat video crossing an ocean — rides fibre-optic cables on the seabed, a few dozen thick as a garden hose laid by specialised ships, repeater-powered every 60–100 km. Satellites carry a thin, slower slice. The cloud is not in the sky; it is warehouse rows in specific countries, and the internet is the sum of private networks that agreed to hand each other traffic at exchange points.',
      ],
      k: ['Messages are packeted, routed independently and reassembled — no central switch exists', 'DNS is a cached global phone book; most “it works for me” mysteries are stale cache', 'Seabed fibre carries ~99% of intercontinental data — the cloud is physical'],
      q: { s: 'Why does the internet keep working after a major link is cut?', o: ['Satellites automatically take over', 'Routers re-find paths around the break', 'Packets wait at the cut until it heals'], a: 1, e: 'Path-free routing is the design goal: every router picks the best current neighbour, so traffic flows around damage within seconds — no takeover required.' } },
    { s: 'inside-a-browser', t: 'Inside the Browser', mn: 6,
      sum: 'From a typed URL to a rendered page: the 200 ms production line.',
      p: [
        'Press Enter and your browser runs a pipeline. It checks its cache for the DNS answer; failing that asks the recursive resolver. With an address in hand it opens a TCP connection, then for HTTPS performs the TLS handshake — verifying the site’s certificate chain (issued by certificate authorities whose roots your browser ships with) and agreeing on encryption keys. Then, and only then, it asks for the page: HTTP GET, status back — 200 found, 404 missing, 301 moved — followed by the HTML.',
        'The HTML is a construction order, not a picture: the browser parses it into a tree, fetches every referenced script, stylesheet and image — discovering more requests as it goes — and paints. Scripts can block the layout like workmen arguing in a doorway, which is why “defer” and smaller images decide whether a page feels fast more than servers do. Every element you see on this page passed that funnel; a “laggy” website is usually a heavy one, not a distant one.',
        'State is the final trick: HTTP itself forgets you between requests — every page load is an amnesia — so the browser carries identity: cookies (small labelled tokens the server re-reads on each visit, for login sessions and preferences), localStorage (bulkier notes the server never sees), and cache (copies of assets so revisits paint without re-downloading). Privacy-wise the honest framing: cookies enable both “stay signed in” and “be followed across sites”; the modern browser now quarantines the second use by default.',
      ],
      k: ['HTTPS = address lookup, connection, certificate verification, key agreement — before any content', 'HTML is a build order; scripts and images are discovered and fetched as it parses', 'HTTP forgets you every request; cookies and localStorage are the browser’s memory'],
      q: { s: 'A hard refresh (bypassing cache) forces the browser to re-fetch:', o: ['Only the HTML', 'The referenced scripts, styles and images too', 'Nothing — cache is server-side'], a: 1, e: 'The build order lists every asset; refreshing re-requests them all from the network instead of reusing local copies — which is why it feels slow.' } },
    { s: 'passwords-2fa', t: 'Passwords, 2FA and Passkeys', mn: 7,
      sum: 'Why length beats complexity, reuse is the real killer, and the key in your pocket.',
      p: [
        'Attackers do not guess one password; they try billions. When a site is breached, its stolen list is run automatically against every other site you use — credential stuffing — which makes reuse the single deadliest habit, far ahead of “password123” itself. A long random phrase (four unrelated words) beats a short complex one because guessing scales with length exponentially: the character-class tricks humans invent (capital Q, exclamation at the end) are the first patterns every cracking tool tries. A password manager fixes the physics: one strong memorised master key, unique 16+ character random passwords everywhere else, autofill so you never type — and never have to reuse.',
        'Second factors plug the leak: if your password escapes, 2FA means the attacker still cannot log in without a device only you hold. App-generated or push codes (time-based one-time codes, cryptographic approvals) are strong; SMS codes are better than nothing but interceptable via the telecom tricks of SIM-swapping. The newest tier is the passkey: a cryptographic keypair generated and held inside your device or its secure element, where the private half literally cannot be extracted or transmitted. Login becomes a signature challenge bound to the exact site, so even a perfect phishing page cannot make the device sign its requests — passkeys are the first defence that fixes phishing at the math level, and this site supports them.',
        'The ordering to remember: uniqueness first (manager), strength second (random), 2FA third (app or passkey), and for high-value accounts the passkey replaces the password rather than joining it. Recovery codes printed and stored offline are the boring final step everyone skips until they need them.',
      ],
      k: ['Reuse, not weakness, is what breaches exploit — unique per-site is the real defence', 'Length scales guessing cost exponentially; “complexity” patterns are tried first', 'Passkeys bind a non-extractable device key to the exact site — phishing-proof by construction'],
      q: { s: 'Why are passkeys resistant to phishing in a way passwords are not?', o: ['They are longer', 'The private key never leaves the device and signatures are bound to the real site', 'They are sent encrypted'], a: 1, e: 'A fake site receives a challenge it cannot answer: your device signs only for the legitimate origin, and the secret itself is never transmitted anywhere.' } },
    { s: 'encryption', t: 'Encryption: Math You Can Sit On', mn: 8,
      sum: 'Symmetric, asymmetric, and what the padlock genuinely promises you.',
      p: [
        'All crypto solves one awkward fact: you want to share secrets with someone you have never met, over a line the whole world can read. Symmetric encryption (one key for both sides, fast, used for the bulk of every connection) needs the key agreed first — impossible over an open line. The fix is a public-key handshake: each side can post an encryption key that locks but cannot unlock (mathematical one-way functions: products of huge primes, elliptic curves), so anyone can send a sealed question, and only the holder of the matching private key can open and answer. A negotiated symmetric key rides inside, and the rest of the session is cheap and fast. The lock is only as good as verification: “key exchange” without identity is why certificate authorities, chains of trust and pinned keys exist — otherwise a middleman locks to you and to the site and reads both.',
        'What the padlock honestly means: the line is encrypted and the server proved its identity for that domain. What it does not mean: the site is safe, honest or unlogged. HTTPS is table stakes now (most web traffic runs on it, browsers mark the rest “Not secure”); the remaining weak links are endpoints — malware on your device sees plaintext because decryption has to end somewhere — and metadata: who you visited, when and how often. End-to-end encryption (messaging apps, and this site’s T Chat) moves the keys to the participants, so even the carrier server reads nothing; the caveat is backups and device access, where the plaintext still lives.',
        'Two honest tensions to be able to argue: mathematics cannot build a backdoor that only good actors use — a weakness that works for the intercepting agency works equally for whoever steals or breaks it — and post-quantum migration is already underway: future large quantum computers threaten today’s public-key schemes (not symmetric or hashes, halved at worst), so standards and mixed key exchanges are shipping now, quietly, in browser and server updates you have already received.',
      ],
      k: ['Public keys lock, private keys unlock — the handshake that makes the open line secret', 'The padlock proves the line and the domain, not the honesty of the site', 'End-to-end means servers read nothing; endpoints and metadata remain the soft spots'],
      q: { s: 'Why is symmetric crypto alone not enough to secure a web session?', o: ['It is slower than public-key math', 'Both sides need the same secret first — and there is no safe line to agree it on yet', 'It is banned for web use'], a: 1, e: 'The chicken-and-egg of key exchange is exactly what public-key handshakes solve; symmetric ciphers then carry the actual traffic because they are fast.' } },
    { s: 'ai-llm-basics', t: 'Large Language Models, Demystified', mn: 8,
      sum: 'The next-word machine: what an AI like our chat does, and what it cannot.',
      p: [
        'A large language model is a neural network trained to predict the next piece of text — it reads a prompt as context and outputs, token by token, a continuation shaped by everything it ever saw during training. “Token” is a fragment of word; training means nudging hundreds of billions of connection weights so statistical patterns of language (grammar, facts, styles, structure) end up encoded as numbers. That is the whole recipe: no lookup table, no live internet, no database of answers — a machine that has read so much text it can imitate its shape, and the imitation is often the real thing.',
        'The consequences are predictable and honest to state. Strengths follow from the shape of language: summarising, translating, drafting, explaining, coding — tasks where knowing “what typically comes next in excellent text” is the actual skill. Weaknesses follow too: the model has no fact-checker inside, only probability, so it produces confident nonsense (“hallucination”) when the likeliest-sounding continuation happens to be wrong; it does not know yesterday’s news if it was not in the training data or search tools; and arithmetic is pattern-matching, not a calculator. RAG — retrieval-augmented generation, fetching real documents and feeding them in as context — is how good systems (including this site’s AI Sembang and search answers) bolt grounding onto the generator.',
        'Practical use is a skill called prompting: state the goal, the format and the constraints, give an example when the style matters, and split big asks into steps — the model improves dramatically when told what “good” means. The judgment rule: treat fluent output as a draft from a fast, well-read intern, never a verdict from an oracle; anything checkable should be checked, and this site keeps a search box for exactly that reason.',
      ],
      k: ['LLMs predict next tokens from trained patterns — they store style and statistics, not a database', 'Hallucination is probability without a fact-checker; retrieval grounding fixes much of it', 'Prompting = describing “good”; verification stays human'],
      q: { s: 'Why can an LLM state a plausible-but-wrong “fact” with total confidence?', o: ['It is lying to be helpful', 'It predicts likely text, and fluent-sounding ≠ verified', 'Its database is out of date'], a: 1, e: 'There is no separate truth module; output is the most probable continuation of the pattern, so confident style and wrong content share the same mechanism.' } },
  ],
  things: [
    { s: 'fridge-heat-pump', t: 'The Fridge: A Heat Courier', mn: 6,
      sum: 'Cooling is not removing cold — it is pumping heat out, and the same trick can heat a house.',
      p: [
        'A fridge cannot “make cold”; physics only moves heat, from wherever it is convenient to be to wherever you insist. So a fridge is a courier: a compressor pushes a refrigerant — a fluid chosen to boil near freezing — around a loop. Upstream of the compressor the gas is squeezed hot and dumps its heat through the coils at the back (that warmth is the fridge doing its job — feel it and you have found where your kitchen’s heat went). Downstream it rushes through a narrow expansion valve, pressure plummets, and the cold boiling fluid absorbs heat from inside the box in the evaporator. Loop again, forever. Cold inside, hotter outside, energy bill paying for the pump.',
        'Run the same machine backwards — pull heat from the cold outdoors and push it inside — and it is a heat-pump heater or air conditioner. The genius is the exchange rate: for each unit of electrical work it can move two to five units of heat, because moving beats generating. This is why heat pumps out-efficiency electric resistance heaters roughly 3:1 and why “efficient cooling” in a hot climate is the same hardware, reversed.',
        'The closing detail that answers a kitchen argument: leaving the fridge door open does not cool the room. The unit just moves heat from the box into the room and adds its compressor waste on top; the net effect is warming, like every machine that claims to make cold anywhere — the AC drip outside your window is the receipt.',
      ],
      k: ['Refrigerants boil under low pressure to absorb heat and condense under pressure to release it', 'A heat pump is a fridge aimed the other way — same loop, moved heat, 2–5× the work', 'An open fridge warms the room: you pay the compressor plus the dumped heat'],
      q: { s: 'The back or underside of a fridge is warm because:', o: ['The motor is inefficient', 'That is where extracted heat is dumped on its way outside', 'Insulation leaks inwards'], a: 1, e: 'The condenser coils release the heat pumped out of the box (plus the compressor’s share) into your kitchen — cooling inside means heating somewhere.' } },
    { s: 'microwave-oven', t: 'The Microwave Oven', mn: 6,
      sum: 'Non-radioactive light that shakes water hot — and the myths that never die.',
      p: [
        'A magnetron generates radio waves at 2.45 GHz — the same family of frequency as Wi-Fi and Bluetooth, far below anything that can damage DNA (ionising radiation starts hundreds of thousands of times higher in energy). Inside the shiny box the waves form standing patterns, and water molecules — little electric dipoles — are flipped back and forth billions of times a second by the alternating field; molecular friction turns that agitation into heat, mostly in the water-rich parts of the food. Metal is banned because it acts as an antenna: induced currents build until they arc across points, pitting the walls.',
        'The honest physics of “cooked from the inside out” is a myth with a twist: the waves penetrate only about a centimetre or two into typical food, so heating actually starts at the surface layers and spreads inward by conduction, exactly like a conventional oven but from both sides of a thin portion. That is also why a dense frozen edge stays cold while the thin centre runs hot, and why the turntable (or a stirring paddle in the mode) exists — the standing-wave pattern has hot and cold stripes roughly hand-width apart, which is why you should leave food to stand after beeping: conduction evens out the stripes.',
        'The dead-simple tests that settle every argument: microwaves do not make food radioactive (the wave energy is too low to alter nuclei — if it were, the oven would be a bomb); they do not “kill nutrients more than other cooking” in any consistent way — any heat degrades some vitamins, and microwaving wins on time and water volume because nutrient loss mostly tracks those two; and the box leaks negligibly when intact, since the mesh in the window has holes far smaller than the 12 cm wavelength it blocks.',
      ],
      k: ['2.45 GHz is radio-band energy: it shakes water dipoles, it cannot break DNA', 'Penetration is ~1–2 cm — microwaves heat from the outside layers in, like any oven', 'Standing-wave hot/cold stripes: that is the turntable and the standing time'],
      q: { s: 'Why does a microwave leave frozen centres cold while edges nearly boil?', o: ['Waves seek the middle first', 'Energy deposits only in the outer centimetre or two; the core heats slowly by conduction', 'Ice reflects microwaves'], a: 1, e: 'Penetration depth in water-rich food is shallow; the middle relies on ordinary heat conduction from the hot outer layer — hence stir and rest.' } },
    { s: 'motor-generator', t: 'Motors and Generators: One Trick, Two Directions', mn: 7,
      sum: 'Coils and magnets, why a fan is also a power plant, and how EVs recharge on hills.',
      p: [
        'The shared secret is the interaction between current and magnetism: a wire carrying current in a magnetic field feels a force (the motor effect), and a wire moving through a magnetic field develops a voltage (Faraday’s induction, the generator effect). One machine, two directions of energy flow. A motor spins because current through a coil on an axle makes it a magnet that the housing magnets keep repelling and attracting — old designs flip the current every half turn with a mechanical commutator; modern ones do it electronically. A generator runs the causality backwards: turn the coil and the magnetic field pushes the electrons, forcing current out.',
        'That reversibility is not trivia — it runs your world. Every grid supply is induction in a turbine hall (steam spun by gas, coal, nuclear, solar-thermal or falling water drags coils past magnets), and every regenerative brake is the same traction motor driven by the wheels instead of driving them, shoving current back into the battery while the car loses altitude or speed — hybrid and EV brake pads last years longer because the motor eats most of the work.',
        'The efficiency story is where motors quietly beat combustion: well-built electric motors convert roughly ninety percent of electrical energy into motion, with the rest shed as heat and noise, while a petrol car manages 20–30% of the fuel’s chemical energy at the wheels, wasting the remainder through exhaust and radiator. It is why a small motor feels instant and a big engine feels hard work: one is a nearly-clean electron conveyor, the other is a heat engine forever fighting the limits of hot-to-cold conversion.',
      ],
      k: ['Current + magnetic field = force; motion + field = voltage — one physics, two machines', 'Regenerative braking is the drive motor acting as a generator, charging while slowing', 'Electric motors: ~90% efficient at the wheels; combustion engines: 20–30%'],
      q: { s: 'An EV going downhill with the motor engaged is:', o: ['Coasting uselessly', 'Generating: the wheels drive the motor as a generator, recharging the pack', 'Reversing the battery polarity'], a: 1, e: 'The drivetrain runs backwards: wheels turn the motor, induction pushes current into the battery, and the machine’s resistance becomes your brake.' } },
    { s: 'batteries', t: 'Batteries: Slow Chemistry, Stored Sunshine', mn: 7,
      sum: 'Li-ion shuttles ions, electrons detour through your phone — and why fuel still wins by weight.',
      p: [
        'A battery is two electrodes soaked in an electrolyte, chosen so that one side “wants” to give up electrons and the other wants to receive them. A phone battery is lithium-ion: the anode (graphite) holds lithium atoms that readily release electrons, the cathode (a lithium-metal oxide) greedily accepts them — and discharge is lithium ions migrating through the electrolyte from one side to the other while their electron partners are forced to detour through your circuit, doing the work on the way. Charging runs the migration backwards, pushing ions home with outside electricity. There is no “charge storage” as a substance: the energy is the strained arrangement of the ions, like a drawn bow.',
        'Cells stack in series to add voltage (each contributes ~3.7 V nominal), and in parallel to add capacity (amp-hours); a battery pack is both plus a battery-management board — the unsung electronics that balance cells, watch temperature and cut the pack before the chemistry ever runs away, because lithium’s energy density cuts both ways. The memory effect people quote is a nickel-cadmium ghost: Li-ion hates deep discharge and heat, not partial cycles, and a laptop kept on the charger or a phone charged from 20 to 80 is healthier than one cycled flat.',
        'The comparison that shapes transport: gasoline stores roughly a hundred times more energy per kilogram than a production Li-ion pack (about 12,000 Wh/kg chemical vs 150–250 Wh/kg cell-level). Batteries win massively on efficiency — round-trip 85–95% vs a heat engine’s 20–30% — so they rule the mobile-electronics and reasonable-range-car world, while ships, planes and long-haul trucks still lean on fuel’s density until the next chemistry comes. Every phone in the room runs on sunshine turned into plants turned into coal or oil or ore, processed by electricity: batteries are stored time as much as stored energy.',
      ],
      k: ['Discharge = lithium ions migrating one way, electrons forced to work on the detour', 'Series adds voltage, parallel adds capacity, the BMS keeps every cell honest', 'Fuel ≈ 100× battery energy by weight; batteries ≈ 3–4× more efficient end-to-end'],
      q: { s: 'A modern phone battery “remembers” partial charging the way old NiCd packs did:', o: ['True — always fully discharge it', 'False — Li-ion prefers partial cycles; deep discharge and heat are what harm it', 'True only below freezing'], a: 1, e: 'The memory effect is a nickel-cadmium phenomenon. Li-ion ages fastest under heat, high state-of-charge stress and deep cycling — shallow top-ups are the friendly habit.' } },
    { s: 'how-planes-fly', t: 'How Planes Fly', mn: 7,
      sum: 'Bent air and pressure differ — two names for one deal the wing makes with the sky.',
      p: [
        'A wing does one thing: it turns air. Shape and angle deflect oncoming flow — most visibly downward — and Newton’s third law returns the favour: the air pushed down pushes the wing up. The same deflection is also read as pressure: air accelerated over the curved upper surface arrives at the trailing edge having spent energy speeding, so static pressure above the wing is lower than below, and the higher pressure underneath lifts. The Bernoulli-vs-Newton arguments online are the same fact told from two textbooks; the wing cares about neither brand, only the circulation it sets up. Lift grows with air density, wing area, and the square of speed — double the speed and you quadruple the lift, which is why takeoff rolls matter and light planes can land at walking-ish speeds.',
        'Control is the same physics in miniature: ailerons tilt the wings for roll, the elevator tips the nose for climb and descent, the rudder yaws for coordinated turns — banking converts lift into a turning force (a level-turning plane tilts precisely so its “upward” push both holds altitude and curves the path). At the edges, flaps extend camber for slow flight on takeoff and landing, slats delay the stall, and wingshop dimples and winglets each trim drag in their way. A stall is not engine failure: it is the airflow detaching from the upper surface because the wing met the air too steeply; the recovery is universally taught — lower the nose to reattach the flow.',
        'The cruising details answer the questions people actually ask. Jets climb to 10–12 km not to escape anything but because thin, cold air means less drag and efficient engines there, and the cabin is pressurised to the equivalent of roughly 2,000–2,400 metres — you feel it as mild altitude, and it is a weight compromise, not a sea-level luxury. The white line behind a high plane is a contrail: exhaust water condensing and freezing on soot particles in icy upper air — literally a thin artificial cloud, sometimes lingering into cirrus that, in aggregate, has a real (small, short-lived) climate effect of its own.',
      ],
      k: ['Lift = air deflected downward = lower pressure above the wing; one physics, two tellings', 'Lift scales with speed squared: the reason takeoff runs and slow flight need flaps', 'A stall is detached airflow from too steep an angle — recovery starts by lowering the nose'],
      q: { s: 'An aircraft flying a level turn must bank because:', o: ['The rudder needs help', 'Tilting the lift vector supplies the sideways force that curves the path', 'To show passengers the horizon'], a: 1, e: 'In level flight lift points up; in a turn, the tilted lift’s horizontal component pulls the plane around the corner while the vertical part still holds altitude.' } },
  ],
  thinking: [
    { s: 'correlation-causation', t: 'Correlation Is Not Cause', mn: 7,
      sum: 'Ice cream and drownings, spurious charts, and what actually proves a cause.',
      p: [
        'Two numbers that rise together prove nothing, because the third variable is usually holding the umbrella. Ice cream sales and drowning deaths track each other perfectly across the year — summer causes both, and neither causes the other. This “confounder” is the commonest culprit: a hidden factor moves both curves, and the pair looks meaningful forever. A second trap is direction: do people with strong social ties stay healthier because ties protect them, or do healthy people find the energy to keep ties? Both stories fit the same correlation, and the answers lead to different interventions. The third is selection: happy people post more photos, but the posting did not create the happiness — the visible sample was never random.',
        'The absurd ends make the point stick: an annual dataset (the famous Spurious Correlations archive) pairs Nicolas Cage film counts with pool-drowning deaths at r ≈ 0.66, and margarine consumption with divorce rates in the same state. No mechanism, pure coincidence — and with thousands of variables and a year of wiggles each, dozens of perfect-looking matches are not just possible, they are guaranteed. The lesson generalises: a chart’s persuasiveness is unrelated to its truth; the question that separates them is “what is the mechanism, and how was the comparison made?”',
        'Causal evidence comes from designs, not correlations: a randomised trial (assign the exposure by lottery, so the only systematic difference between groups is the thing you changed), natural experiments (policy boundaries, staggered rollouts), or a mechanism tight enough to rule coincidence out in physics and chemistry. Where those are absent — most headline science — the honest sentence is “associated with”, and whenever you catch yourself writing or believing “leads to / increases / causes” from a pair of moving lines, you have the right reflex: what moved them both?',
      ],
      k: ['Confounders, reverse direction and selection can all explain any A↔B link', 'Big datasets guarantee pretty matches with zero mechanism — check the process, not the r²', 'Only randomisation or true experiments convert “correlated” into “caused”'],
      q: { s: 'Firefighters sent to bigger fires have worse average damage outcomes. Does sending more firefighters cause worse damage?', o: ['Yes — the correlation is strong', 'No — fire severity confounds both; you are seeing selection, not cause', 'Only at night'], a: 1, e: 'The worst fires draw the most crews. Comparing unbalanced situations is the classic confound; randomising response (unethical!) or controlling for severity is the fix.' } },
    { s: 'confirmation-bias', t: 'The Mind That Only Wants to Be Right', mn: 7,
      sum: 'You search for confirmations, not tests — and your feed knows it.',
      p: [
        'Confirmation bias is the default setting of human thinking: we gather evidence that flatters what we already believe, interpret ambiguity in its favour, and remember its hits while forgetting its misses. The classic lab demonstration: given a number sequence obeying a hidden rule, people overwhelmingly test by proposing sequences that confirm their guess instead of sequences that could falsify it — and stay wrong confidently. The same machinery runs at reading scale: the article you would believe without checking is the one you already agree with, and the one that makes you fact-check hardest is the one that challenges you — which produces the perverse result that believers in a claim end up with more exposure to reasons for it than reasons against it.',
        'Social media turned a private weakness into infrastructure: feeds optimise for engagement, engagement rewards agreement and outrage, and both push you toward content that confirms — the filter-bubble effect is real in measurement but weaker than either pole claims (people’s networks do leak across lines; the stronger effect is self-selection: you click what flatters you). The more useful framing is that algorithms do not need to censor anything to bias you: they only need to sort your attention by what feels right.',
        'The counter-moves are boring and they work. Steelman: restate the opposing position until someone who holds it says “yes, that is it” — before answering. Premortem: assume you are already wrong and ask what evidence would have shown it — then go find exactly that. Ask the asymmetry question: would I demand this standard of proof from a claim I liked? And notice the feeling: comfort is not evidence — the sentence “this is obviously true” deserves more suspicion when it feels good than when it grates.',
      ],
      k: ['We test to confirm, not to falsify — the bias is about information-seeking, not stubbornness', 'Feeds exploit it commercially: sorting attention by “feels right” needs no censorship', 'Steelman + premortem + asymmetric-proof check are the three cheap counter-moves'],
      q: { s: 'The most diagnostic question about a belief, per falsification practice, is:', o: ['How many people agree with me?', 'What observation, if it happened, would prove me wrong?', 'Does it make me feel good?'], a: 1, e: 'A claim that forbids no possible observation is untestable; naming the falsifier in advance converts “I believe” into “I have been tested”.' } },
    { s: 'stats-in-headlines', t: 'Statistics in Headlines', mn: 8,
      sum: 'Risk doubled from tiny is still tiny, subgroups torture truth, and n hides in footnotes.',
      p: [
        'The relativity trick: “brain tumour risk doubles with X” sounds apocalyptic and may mean 1 in 10,000 becoming 2 in 10,000. Relative risk multiplies; absolute risk adds — and only the absolute version lets you decide anything sane. Whenever a headline gives you a percentage increase, hunt the baseline: the same result honestly stated as “an extra one case per 10,000 people” often reverses the emotional conclusion.',
        'The subgroup trick: slice data enough ways and “significant” findings appear by chance alone. Screen 20 outcomes at the usual p<0.05 bar and statistically you expect about one false positive even when nothing is true; the “works only in men under 40” finding is usually that stray. This is not hypothetical — psychology and medicine have lived a replication crisis: landmark findings repeatedly failing retesting, p-hacking (collecting, slicing and modelling until the threshold trips) now estimated to inflate a substantial share of published positives. The 2010s correction — pre-registration, larger samples, open data — is real but incomplete.',
        'The checklist that survives contact with any study article: how many subjects (a finding from 12 people is anecdote with decimals)? Compared against what (control group, or before-after with time confounds)? Measured or self-reported? Published in a venue that peer-reviewed it, or a press release? Who funded the analysis? And finally, the meta-rule the whole academy teaches: one study is never a verdict — science accumulates in the boring direction, and the trustworthy claim is the one several independent groups have now failed to knock down.',
      ],
      k: ['Always convert relative risk back to absolute numbers before feeling anything', '20 cuts of nothing produce one “hit”: subgroups and p-hacking manufacture findings', 'Sample, control, funding and replication are the four footnotes that change conclusions'],
      q: { s: '“Risk rises 100%!” from 0.01% to ___.', o: ['0.02%', '1%', '2%'], a: 0, e: 'A doubling of 0.01% is 0.02% — one extra case in ten thousand. “100% increase” is the same arithmetic with the decimal point hidden.' } },
    { s: 'base-rate-fallacy', t: 'Tests, Positives and Base Rates', mn: 8,
      sum: 'Why a “99% accurate” test can still leave your positive result ~99% wrong.',
      p: [
        'A screening test is a machine that fires when things are wrong — and sometimes when they are not. Take a disease affecting 1 in 10,000 and a genuinely excellent test: it flags 99% of true cases and false-alarms on 1% of healthy people. Run it on 100,000 people. Expect about 10 sick and 99,990 healthy. The sick mostly light up: ~10 true positives. But the healthy produce ~1,000 false positives — the base is so huge that 1% of it dwarfs the disease. Now you have about 1,010 positives and only ten of them are real: a positive result means roughly 1% chance of disease, not 99%. This is the base-rate fallacy in one arithmetic block, and it is why any positive screening test demands a confirmatory test, ideally with a different mechanism.',
        'The same arithmetic polices your whole information diet. “This symptom matches a rare condition” — the common conditions are common for a reason; a match to a rare profile is far more likely the thousand-to-one false positive than the disease. “This stock tip matches patterns that worked twice before” — the base rate of tips beating the market is near zero, so the pattern evidence needs a huge likelihood ratio to move the prior at all. Bayes’ rule is not a formula to memorise; it is the discipline of letting the rarity of a thing discount the strength of signals about it.',
        'The honest flip side: the base-rate reasoning cuts both ways. When a test is extremely specific and the population enriched (a specialist referring high-risk patients), positives genuinely mean something. The skill is never “trust the test” or “distrust the test” but knowing which population you are in — your prior is a number, and you can update it the same way you update everything else.',
      ],
      k: ['False positives = error rate × the huge healthy majority; they can swamp real cases', 'A “99% accurate” positive on a 1-in-10,000 disease is ~99% likely wrong', 'Base rates are the missing number in almost every alarmist statistic'],
      q: { s: 'In the 1-in-10,000 / 99%-sensitive / 1%-false-positive example, a positive means roughly:', o: ['99% disease', '~50/50', '~1% disease'], a: 2, e: 'About 10 true vs ~1,000 false positives among 100,000 tested: a positive lands the patient in the ~1,010 pool with 10 cases — near 1%.' } },
    { s: 'fact-checking-method', t: 'How to Check Anything Online', mn: 7,
      sum: 'Read sideways, find the primary source, and let the date do the talking.',
      p: [
        'Professional fact-checkers do not study a suspicious page — they leave it. “Lateral reading” means opening new tabs immediately to see what independent sources say about the claim and the publisher; the domain’s own About page tells you what it wants you to believe, while the ecosystem tells you what it is. The single most productive move is tracing to primary source: the study, the court document, the raw video, the official statement. Quotes that cannot be found anywhere upstream are usually invented or shredded, and a press release summarising “research” without a paper is a claim, not evidence.',
        'Two cheap forensic habits catch most fakes. Check the date in the metadata and the URL, not the article’s layout: the internet recycles — old disaster photos ride every new disaster, and a story can be true-in-2015 and false-now with identical pixels. Reverse-image search every photo that carries the argument; the mismatch between a genuine image and a wrong caption is the most common misinformation pattern, ahead of any fabrication. For text, the giveaway is structure: do the numbers point at a citable dataset, does “studies show” ever name one, is the emotional load carried by adjectives instead of facts?',
        'The final skill is deciding what to do with uncertainty, and the honest rule is proportional: extraordinary claims need sources that would embarrass a law clerk, but ordinary claims need not be verified before they stop surprising you — the bottleneck is outrage, not doubt. Pause before forwarding, because sharing is endorsement you do not withdraw; correct your own past shares out loud where it helps; and keep one permanent asymmetry: demand more evidence from claims that flatter you than from claims that threaten you — that gap is where every grifter, including the ones in your own echo chamber, makes their living.',
      ],
      k: ['Read sideways off the page; the ecosystem describes a source better than it does itself', 'Primary source or it is a rumour; dates and reverse-image catch most recycled fakes', 'Share = endorse — the pause before forwarding is the whole intervention'],
      q: { s: 'A shocking quote with no traceable original is best handled by:', o: ['Trusting the site that published it', 'Searching for the primary document; absence of upstream = treat as unverified', 'Reposting with a sceptical caption'], a: 1, e: 'Verifiable claims have chains: publisher → outlet → document. Where the chain starts nowhere, the claim is this site’s copy of nothing, however confidently typeset.' } },
  ],
};

// ——— Helpers ———
function trackList() {
  return TRACKS.map((t) => Object.assign({}, t, { count: (LESSONS[t.s] || []).length }));
}
function findTrack(slug) { return TRACKS.find((t) => t.s === slug) || null; }
function findLesson(trackSlug, lessonSlug) {
  return (LESSONS[trackSlug] || []).find((l) => l.s === lessonSlug) || null;
}
function totalLessons() { return Object.values(LESSONS).reduce((n, a) => n + a.length, 0); }
// Semua pelajaran dengan nombor global & rujukan trek — untuk sitemap & nav prev/next.
function allLessons() {
  const out = [];
  let n = 0;
  for (const t of TRACKS) for (const l of (LESSONS[t.s] || [])) out.push(Object.assign({}, l, { track: t, no: ++n }));
  return out;
}

module.exports = { TRACKS, LESSONS, trackList, findTrack, findLesson, totalLessons, allLessons };
